            lst.sort(key=lambda x:(x.start,x.end,x.order))
            self.starts[chrom]=[r.start for r in lst]
        self.records=records
    def find(self, a_rec, spec, sort_by_order=True):
        lst=self.by.get(a_rec.chrom,[])
        if not lst: return []
