# Bin-indexed version for large files: If number of records per chrom large, scanning prefix may be heavy.
# Implement BinDB using 16k bins
class BinDB:
    BIN=16384
    def __init__(self, records):
        from collections import defaultdict
        self.bins=defaultdict(list) # (chrom,bin)->records
        self.by_chrom=defaultdict(list)
        for r in records:
            self.by_chrom[r.chrom].append(r)
            s=r.start-1 if r.zero else r.start
            e=r.end+1 if r.zero else r.end
            if e<=s: e=s+1
            b1=max(0,s//self.BIN); b2=max(0,(e-1)//self.BIN)
