        eff=a_rec.effective_intervals(split)
        s=min(x for x,y in eff); e=max(y for x,y in eff)
        seen=set(); cand=[]
        b1=max(0,s//self.BIN); b2=max(0,(max(e-1,s))//self.BIN)
        for b in range(b1,b2+1):
            for r in self.bins.get((a_rec.chrom,b),[]):
                if id(r) not in seen:
                    seen.add(id(r)); cand.append(r)
        for r in self.bins.get((a_rec.chrom,-1),[]):
            if id(r) not in seen:
                seen.add(id(r)); cand.append(r)
        return cand
    def find(self,a_rec,spec,sort_by_order=True):
        cand=self.candidates(a_rec,spec.split)
        res=[]
        for b in cand:
            ok,ov=spec.check(a_rec,b)
            if ok: res.append((b,ov))
        if sort_by_order:
            res.sort(key=lambda t:t[0].order)
        return res
    def find_any(self,a_rec,spec):
        for b in self.candidates(a_rec,spec.split):
            ok,ov=spec.check(a_rec,b)
            if ok: return True
        return False

