        return self.end-self.start
    def __repr__(self):
        return f"Record({self.line!r})"
    def to_line(self):
        return "\t".join(self.fields)
    def copy_with_coords(self, new_start, new_end, new_chrom=None):
        fields=list(self.fields)
        chrom = new_chrom if new_chrom is not None else self.chrom
        # build new record then modify fields correctly per fmt
        rec = Record.__new__(Record)
        rec.fields=fields
        rec.chrom=chrom; rec.start=int(new_start); rec.end=int(new_end); rec.strand=self.strand; rec.name=self.name; rec.fmt=self.fmt; rec.nfields=len(fields); rec.order=self.order; rec.blocks=self.blocks; rec.zero=(rec.start==rec.end); rec.bam=self.bam; rec.file_id=self.file_id; rec.extra=self.extra; rec.score_str=self.score_str
        # modify fields
        if rec.fmt=="bed":
            if len(fields)>=1: fields[0]=chrom
            if len(fields)>=2: fields[1]=str(rec.start)
            if len(fields)>=3: fields[2]=str(rec.end)
        elif rec.fmt=="gff":
            if len(fields)>=1: fields[0]=chrom
            if len(fields)>=4: fields[3]=str(rec.start+1)
            if len(fields)>=5: fields[4]=str(rec.end)
        elif rec.fmt=="vcf":
            if len(fields)>=1: fields[0]=chrom
            if len(fields)>=2: fields[1]=str(rec.start+1)
            # end not repr (except maybe INFO END) leave
        elif rec.fmt=="bedpe":
            # not used
            pass
        else:
            if len(fields)>=1: fields[0]=chrom
            if len(fields)>=2: fields[1]=str(rec.start)
            if len(fields)>=3: fields[2]=str(rec.end)
        rec.line="\t".join(fields)
        return rec
    def set_coords_inplace(self, new_start, new_end):
        new=self.copy_with_coords(new_start,new_end)
        self.fields=new.fields; self.start=new.start; self.end=new.end; self.line=new.line; self.zero=new.zero
        return self
    def effective_intervals(self, split=False):
        if split and self.blocks:
            return list(self.blocks)
        if self.bam is not None and split and getattr(self.bam,"blocks",None):
            return list(self.bam.blocks)
        if self.zero:
            return [(self.start-1, self.end+1)]
        return [(self.start, self.end)]
    def overlap_len_effective(self, other, split=False):
        # sum of overlaps of effective intervals
        total=0
        for s,e in self.effective_intervals(split):
            for s2,e2 in other.effective_intervals(split):
                ov = min(e,e2)-max(s,s2)
                if ov>0: total+=ov
        return total
    def overlap_len_reported(self, other, split=False):
        # value printed by -wo etc.
        if self.zero and other.zero:
            # if they overlap effectively
            if self.overlap_len_effective(other,split)>0:
                return -2
            else:
                # not called
                return self.overlap_len_effective(other,split)
        if self.zero:
            return 0 if self.overlap_len_effective(other,split)>0 else 0
        if other.zero:
            if other.start==self.start or other.start==self.end:
                return -1
            return 0
        # normal, possibly split
        if split and (self.blocks or other.blocks or (self.bam and getattr(self.bam,"blocks",None)) or (other.bam and getattr(other.bam,"blocks",None))):
            return self.overlap_len_effective(other,True)
        ov=min(self.end,other.end)-max(self.start,other.start)
        return ov if ov>0 else ov  # for reporting in overlap tool etc caller handles

class FileInfo:
    def __init__(self, path, fmt="bed", nfields=3, header=None, is_bam=False, bam_header=None, refs=None):
        self.path=path
        self.fmt=fmt
        self.nfields=nfields
        self.header=header or []
        self.is_bam=is_bam
        self.bam_header=bam_header
        self.refs=refs or []
    def null_record_fields(self):
        # Generate NULL B record fields according to format
        fmt=self.fmt; n=self.nfields
        if fmt=="gff":
            return [".",".",".","-1","-1",".",".",".","."][:n] if n>=9 else [".",".",".","-1","-1",".",".",".","."]
        if fmt=="vcf":
            # 8 fields default
            base=[".","-1",".",".",".",".",".","."]
            if n>8:
                base+=["."]*(n-8)
            return base[:max(n,8)]
        if fmt=="sam":
            # unlikely
            return [".","-1","-1"]
        # bed / bedpe?
        if fmt=="bedpe":
            # e.g. 10 fields: chrom1 etc . -1 -1 . -1 -1 . -1 . . ??? investigate later
            # fallback pattern
            return [".","-1","-1",".","-1","-1",".","-1",".","."][:n]
        # bed
        if n==3:
            return [".","-1","-1"]
        if n==4:
            return [".","-1","-1","."]
        if n==5:
            return [".","-1","-1",".","-1"]
        if n==6:
            return [".","-1","-1",".","-1","."]
        if n==12:
            return [".","-1","-1",".","-1","."]+["."]*6
        # bed plus
        return [".","-1","-1"]+["."]*(n-3)
    def null_line(self):
        return "\t".join(self.null_record_fields())

def detect_format_from_headers_and_first(headers, first_fields_list):
    # header hints
    for h in headers:
        if h.startswith("##fileformat=VCF"):
            return "vcf"
        if h.startswith("#CHROM") or h.startswith("#chr"):
            # vcf header line #CHROM...
            pass
    # also if any header is vcf chrom line
    for h in headers:
        if h.startswith("#CHROM"):
            return "vcf"
    return None

def parse_record_fields(fields, fmt_hint=None, header_hint=None):
    """Try to parse fields into (chrom,start,end,strand,name,fmt). Return None if fail."""
    # VCF hint
    if header_hint=="vcf" or fmt_hint=="vcf":
        if len(fields)>=5 and is_int_str(fields[1]):
            pos=int(fields[1]); ref=fields[3] if len(fields)>3 else "N"
            # END in INFO?
            end=None
            if len(fields)>=8:
                info=fields[7]
                # parse END=...
                m=re.search(r'(?:^|;)END=(\d+)',info)
                if m:
                    end=int(m.group(1))
                # SVLEN?
            if end is None:
                # ref length, but if symbolic <...> length 1?
                if ref.startswith("<"):
                    end=pos  # pos-1 +1
                else:
                    end=pos-1+len(ref)
            else:
                # VCF END is 1-based inclusive => half open end = END (?)
                # bedtools: for VCF with END, end = END ??? check: pos = start-1, end = END (since inclusive last base +1?) If END=200, bases pos..200 inclusive (?) end=200
                pass
            return (fields[0], pos-1, end, ".", fields[2] if len(fields)>2 else ".", "vcf")
        else:
            return None
    # Try BED: cols2,3 ints, start<=end
    if len(fields)>=3 and is_int_str(fields[1]) and is_int_str(fields[2]):
        s=int(fields[1]); e=int(fields[2])
        if s<0 or e<s:
            # bad3 case e<s -> type determination fails for new tools; old tools may still? return None to trigger error in new; caller can fallback
            return None
        name=fields[3] if len(fields)>=4 else "."
        strand=fields[5] if len(fields)>=6 else "."
        # For BED, strand field if present in std 6/12 must be + - . ; if bed plus, col6 may be other; strand extraction for -s in bedplus? bedtools may treat strand as '.' if not std? Hmm:
        # If nfields is 6 or 12, strand is fields[5]; else if >6 but not 12, it's BED plus where extra fields after 6, but strand still col6? Earlier merge etc with BED6+ extra... In null generation they treated as plus, but strand for -s may still use col6 if it's +/-/. Keep if in set else '.'
        if strand not in ("+","-","."):
            strand="."
        return (fields[0], s, e, strand, name, "bed")
    # Try GFF: 9 fields, cols4,5 ints
    if len(fields)>=9 and is_int_str(fields[3]) and is_int_str(fields[4]):
        s=int(fields[3])-1; e=int(fields[4])
        if s<0: s=0
        strand=fields[6] if len(fields)>6 else "."
        if strand not in ("+","-","."):
            # GFF strand could be "?" keep dot for matching?
            strand="."
        # name: try parse attributes ID / Name?
        name="."
        # GFF name used in some tools? closest -N compares name field - for GFF maybe ??? attributes?
        return (fields[0], s, e, strand, name, "gff")
    # Try VCF without header maybe: fields[1] int, fields[3] ref bases only ACGT etc and len>=8
    if len(fields)>=8 and is_int_str(fields[1]):
        # but this would have been BED fail due fields[2] not int
        # Require header hint in new tools - we only reach here if caller allows vcf without header for old tools
        pos=int(fields[1]); ref=fields[3]
        end=pos-1+max(1,len(ref)) if not ref.startswith("<") else pos
        return (fields[0], pos-1, end, ".", fields[2], "vcf")
    return None

def read_records(path, style="new", allow_bam=True, bedpe=False, force_fmt=None):
    """Return (records, FileInfo)
    style: "new" => error messages new framework; "old"=> old BedFile errors; "groupby" etc special?
    This reads whole file into memory.
    """
    # stdin handling: path None or stdin or -
    display_path = path if path is not None else "stdin"
    # Check existence for file errors in style
    if path is not None and path not in ("stdin","-") and not path.startswith("/dev/fd/") and path!="/dev/stdin":
        if not os.path.exists(path):
            raise file_open_error(path, style="new" if style=="new" else style)
    # Read raw bytes to check BAM
    try:
        raw = read_binary_raw(path)
    except FileNotFoundError:
        raise file_open_error(display_path, style="new" if style=="new" else style)
    except OSError:
        raise file_open_error(display_path, style="new" if style=="new" else style)
    # BAM detection: BGZF decompress startswith BAM\1, or raw BAM? Also CRAM magic?
    is_bam=False; bam_data=None
    if allow_bam:
        decompressed=None
        if is_gzip_data(raw):
            try:
                decompressed=gzip.decompress(raw)
            except Exception:
                decompressed=None
        else:
            decompressed=raw
        if decompressed is not None and len(decompressed)>=4 and decompressed[:4]==b"BAM\x01":
            is_bam=True; bam_data=decompressed
        elif decompressed is not None and len(decompressed)>=4 and decompressed[:4]==b"CRAM":
            # CRAM unsupported: give error like htslib? For now treat as error
            raise BedError(f"[E::cram] CRAM support not available\n")
    if is_bam:
        from bam import parse_bam
        records, info = parse_bam(bam_data, display_path)
        return records, info
    # Text: decompress gz if needed
    if is_gzip_data(raw):
        try:
            text_bytes=gzip.decompress(raw)
        except Exception as e:
            text_bytes=raw
    else:
        text_bytes=raw
    text=text_bytes.decode('utf-8', errors='surrogateescape')
    lines=text.split("\n")
    if lines and lines[-1]=="" and text.endswith("\n"):
        lines=lines[:-1]
    lines=[l[:-1] if l.endswith("\r") else l for l in lines]
    return parse_text_lines(lines, display_path, style=style, bedpe=bedpe, force_fmt=force_fmt)

def parse_text_lines(lines, display_path, style="new", bedpe=False, force_fmt=None):
    headers=[]
    records=[]
    fmt_hint=force_fmt
    first_nfields=None
    detected_fmt=None
    # SAM detection: if first lines start with @HD etc and later fields are SAM (11+)
    is_sam=False
    # peek headers
    # We'll process sequentially
    order=0
    for idx,line in enumerate(lines):
        if line=="":
            continue
        if is_header_line(line):
            headers.append(line)
            if line.startswith("##fileformat=VCF") or line.startswith("#CHROM"):
                fmt_hint="vcf"; detected_fmt="vcf"
            continue
        # SAM header lines starting with @ but bedtools new may treat as ??? If file is SAM, headers start @
        if line.startswith("@") and (line.startswith("@HD") or line.startswith("@SQ") or line.startswith("@RG") or line.startswith("@PG") or line.startswith("@CO")):
            # Determine if rest looks SAM? We'll treat as header and set sam hint
            headers.append(line)
            is_sam=True
            continue
        fields=line.split("\t")
        # For SAM records: 11+ fields, second field int flag, third chrom, fourth pos
        if is_sam:
            # parse SAM to BED-like record
            # import in bam module
            from bam import sam_record_to_record
            rec=sam_record_to_record(fields, order)
            if rec is None:
                continue
            records.append(rec); order+=1
            if first_nfields is None:
                first_nfields=len(rec.fields); detected_fmt="bed"
            continue
        if bedpe:
            # parse bedpe as record with chrom=start1 etc stored in extra; main record handling in pair tools uses read_bedpe separately.
            # Here just create record representing first end
            pass
        if first_nfields is None:
            # determine format
            parsed=parse_record_fields(fields, fmt_hint=fmt_hint, header_hint=fmt_hint)
            if parsed is None:
                if style=="new":
                    raise BedError(f"Error: unable to open file or unable to determine types for file {display_path}\n\n- Please ensure that your file is TAB delimited (e.g., cat -t FILE).\n- Also ensure that your file has integer chromosome coordinates in the \n  expected columns (e.g., cols 2 and 3 for BED).\n")
                elif style=="old":
                    # Old BedFile messages vary by case; approximate based on fields
                    if len(fields)<3:
                        raise BedError(f"It looks as though you have less than 3 columns at line {idx+1} in file {display_path}.  Are you sure your files are tab-delimited?\n")
                    else:
                        raise BedError(f"Unexpected file format.  Please use tab-delimited BED, GFF, or VCF. Perhaps you have non-integer starts or ends at line {idx+1}?\n")
                else:
                    # for other styles, same as old
                    if len(fields)<3:
                        raise BedError(f"It looks as though you have less than 3 columns at line {idx+1} in file {display_path}.  Are you sure your files are tab-delimited?\n")
                    else:
                        raise BedError(f"Unexpected file format.  Please use tab-delimited BED, GFF, or VCF. Perhaps you have non-integer starts or ends at line {idx+1}?\n")
            chrom,s,e,strand,name,fmt = parsed
            detected_fmt=fmt; first_nfields=len(fields)
            # trailing empty field check for new: if any field == "" (?), type checker fails? Simpler: if last field empty due trailing tab
            if style=="new" and any(f=="" for f in fields):
                raise BedError('Error: Type checker found wrong number of fields while tokenizing data line.\nPerhaps you have extra TAB at the end of your line? Check with "cat -t"\n')
            rec=Record(fields,chrom,s,e,strand,name,fmt,order)
            records.append(rec); order+=1
        else:
            # subsequent
            if len(fields)!=first_nfields:
                if style=="new":
                    raise BedError('Error: Type checker found wrong number of fields while tokenizing data line.\nPerhaps you have extra TAB at the end of your line? Check with "cat -t"\n')
                elif style=="old":
                    raise BedError(f"Differing number of BED fields encountered at line: {idx+1}.  Exiting...\n")
                else:
                    raise BedError(f"Differing number of BED fields encountered at line: {idx+1}.  Exiting...\n")
            if style=="new" and any(f=="" for f in fields):
                raise BedError('Error: Type checker found wrong number of fields while tokenizing data line.\nPerhaps you have extra TAB at the end of your line? Check with "cat -t"\n')
            parsed=parse_record_fields(fields, fmt_hint=detected_fmt, header_hint=detected_fmt)
            if parsed is None:
                if style=="new":
                    # What error does bedtools give for mid file bad int? Probe later; use type checker message
                    raise BedError('Error: Type checker found wrong number of fields while tokenizing data line.\nPerhaps you have extra TAB at the end of your line? Check with "cat -t"\n')
                else:
                    raise BedError(f"Unexpected file format.  Please use tab-delimited BED, GFF, or VCF. Perhaps you have non-integer starts or ends at line {idx+1}?\n")
            chrom,s,e,strand,name,fmt = parsed
            rec=Record(fields,chrom,s,e,strand,name,fmt,order)
            records.append(rec); order+=1
    # empty file
    if detected_fmt is None:
        detected_fmt=fmt_hint or "bed"
        first_nfields=first_nfields or 3
    info=FileInfo(display_path, fmt=detected_fmt, nfields=first_nfields or 3, header=headers)
    return records, info

def read_records_old(path, **kw):
    return read_records(path, style="old", **kw)

