class BEDPERecord:
    __slots__=("fields","chrom1","start1","end1","chrom2","start2","end2","name","score","strand1","strand2","order","line","fmt","nfields")
    def __init__(self, fields, order=0):
        self.fields=list(fields); self.order=order; self.line="\t".join(fields); self.fmt="bedpe"; self.nfields=len(fields)
        self.chrom1=fields[0]; self.start1=int(fields[1]); self.end1=int(fields[2])
        self.chrom2=fields[3]; self.start2=int(fields[4]); self.end2=int(fields[5])
        self.name=fields[6] if len(fields)>6 else "."
        self.score=fields[7] if len(fields)>7 else "."
        self.strand1=fields[8] if len(fields)>8 else "."
        self.strand2=fields[9] if len(fields)>9 else "."
    def to_line(self): return "\t".join(self.fields)

def read_bedpe(path, style="old"):
    if path is not None and path not in ("stdin","-") and not os.path.exists(path) and not path.startswith("/dev/fd/"):
        # pairtobed a error style is old_bedpe
        raise BedError(f"Error: The requested BEDPE file ({path}) could not be opened. Error message: (No such file or directory). Exiting!\n")
    lines=read_text_lines(path)
    headers=[]; recs=[]
    order=0; first_n=None
    for idx,line in enumerate(lines):
        if line=="": continue
        if is_header_line(line):
            headers.append(line); continue
        f=line.split("\t")
        if len(f)<6:
            raise BedError(f"Unexpected file format.  Please use tab-delimited BED, GFF, or VCF. Perhaps you have non-integer starts or ends at line {idx+1}?\n")
        if first_n is None: first_n=len(f)
        elif len(f)!=first_n:
            raise BedError(f"Differing number of BED fields encountered at line: {idx+1}.  Exiting...\n")
        try:
            rec=BEDPERecord(f,order)
        except Exception:
            raise BedError(f"Unexpected file format.  Please use tab-delimited BED, GFF, or VCF. Perhaps you have non-integer starts or ends at line {idx+1}?\n")
        recs.append(rec); order+=1
    info=FileInfo(path or "stdin", fmt="bedpe", nfields=first_n or 10, header=headers)
    return recs, info

# overlap utilities
def strand_match(a,b, mode): # mode None, 's', 'S'
    if mode is None:
        return True
    if mode=='s':
        return a in ("+","-") and a==b
    if mode=='S':
        return (a=="+" and b=="-") or (a=="-" and b=="+")
    return True

def fraction_ok(a_rec,b_rec, overlap_eff, f=None,F=None,r=False,e=False, split=False):
    # defaults: bedtools default f=1e-9 etc. If user didn't specify f/F, they default to 1e-9 (?) but reciprocal handling...
    # Caller provides f_val (default 1e-9) and F_val (1e-9) and flags if specified? Need logic mirroring bedtools:
    # Observed: -f 0.5 alone only checks A fraction. -F alone only B. -f with -r checks both with f value for both.
    # -e changes AND to OR when both f and F are in play.
    # Implementation external uses helper below with explicit specs
    pass

class OverlapSpec:
    def __init__(self, f=1e-9, F=1e-9, f_spec=False, F_spec=False, r=False, e=False, s=False, S=False, split=False):
        self.f=f; self.F=F; self.f_spec=f_spec; self.F_spec=F_spec; self.r=r; self.e=e; self.s=s; self.S=S; self.split=split
    def strand_ok(self,a,b):
        if self.s:
            return strand_match(a.strand,b.strand,'s')
        if self.S:
            return strand_match(a.strand,b.strand,'S')
        return True
    def overlap_eff(self,a,b):
        return a.overlap_len_effective(b,self.split)
    def check(self,a,b):
        if a.chrom!=b.chrom:
            return False,0
        if not self.strand_ok(a,b):
            return False,0
        ov=self.overlap_eff(a,b)
        if ov<=0:
            return False,ov
        # fractions
        # lengths: if split and blocks? bedtools uses overall record length or split total length?
        # For coverage etc, length denominator was overall span (400) not block sum. For intersect -f with BED12 split, likely?
        # Let's use: if split and blocks exist, length = (?) need probe later. For now use span length, but for zero use effective length (2)
        a_len = a.length() if not a.zero else 2
        b_len = b.length() if not b.zero else 2
        # If split, A len maybe sum block lengths? Test later; keep span for now but note -wo overlap uses block sum.
        # Actually for BED12, original record length for fraction in bedtools (FileRecordTools) - they create merged (?) hmm.
        # determine requirements list of (fraction_value, threshold)
        reqs=[]
        # Logic reconstruction:
        # - if r: use f for both (if f_spec or default?) If user gave -F and -r without -f? probably use F? Need probe.
        # Cases:
        if self.r:
            # reciprocal: threshold = f if f_spec else (F if F_spec else f)
            thr = self.f if self.f_spec else (self.F if self.F_spec else self.f)
            reqs=[(ov/a_len if a_len else 0, thr),(ov/b_len if b_len else 0, thr)]
            # e with r ??? if e also, then OR
            if self.e:
                ok = any(val+1e-12 >= t for val,t in reqs) # tolerance?
                # bedtools uses >=? fraction exactly 0.5 passes as seen.
            else:
                ok = all(val+1e-12 >= t for val,t in reqs)
            return ok, ov
        # not reciprocal
        checks=[]
        if self.f_spec:
            checks.append((ov/a_len if a_len else 0, self.f))
        if self.F_spec:
            checks.append((ov/b_len if b_len else 0, self.F))
        if not checks:
            # default 1bp: ov>0 already (but effective ov for zero cases 1 or2 >0)
            # However fraction default 1e-9 means any positive ov passes
            return True, ov
        if self.e:
            ok=any(val+1e-12 >= t for val,t in checks)
        else:
            ok=all(val+1e-12 >= t for val,t in checks)
        return ok, ov

def build_index(records):
    """by chrom -> list sorted by start"""
    from collections import defaultdict
    idx=defaultdict(list)
    for r in records:
        idx[r.chrom].append(r)
    for chrom in idx:
        idx[chrom].sort(key=lambda x:(x.start,x.end,x.order))
    return idx

def find_overlaps(a_rec, b_by_chrom, spec):
    """Return list of (b_rec, overlap_eff) that check() passes, in B file order? bedtools output order for unsorted binning:
    For default (non-sorted) intersect, hits are reported ... in order of B appearance? Or sorted by position? Probe later.
    We'll return in b order as they were in file (their order attribute)?? But binning may produce by start.
    Let's return sorted by b order (original order) to match many cases where B is sorted anyway start==order.
    If -sortout option, caller sorts.
    """
    lst=b_by_chrom.get(a_rec.chrom, [])
    # Use efficient candidate selection using binary search on starts
    # lst sorted by start
    # Candidate b where effective intervals intersect: approximate using record span (or blocks min/max = span, zero expanded)
    a_s = min(s for s,e in a_rec.effective_intervals(spec.split)) if True else a_rec.start
    a_e = max(e for s,e in a_rec.effective_intervals(spec.split))
    # binary search left bound: b.start < a_e (for zero b, b effective start = b.start-1; equivalent b.start-1 < a_e => b.start <= a_e)
    # Use bisect on starts
    import bisect
    starts=[r.start for r in lst]  # this is O(n) per query rebuilding - caller should use IndexedDB class for speed
    hi=bisect.bisect_left(starts, a_e+1)  # allow +1 for zero expansion
    res=[]
    for b in lst[:hi]:
        # quick skip if b effective end <= a_s
        b_e = b.end+1 if b.zero else b.end
        if b_e <= a_s:
            continue
        ok,ov=spec.check(a_rec,b)
        if ok:
            res.append((b,ov))
    res.sort(key=lambda t: t[0].order)
