def fmt_op_num(x, prec=10):
    if isinstance(x,float):
        if math.isinf(x): return "inf" if x>0 else "-inf"
        if math.isnan(x): return "nan"
    return ("%.*g" % (prec, x))

def _to_floats(values):
    out=[]
    for v in values:
        try:
            # bedtools uses strtod ?? values like "1e5" OK, "." fails
            # Also empty?
            out.append(float(v))
        except:
            return None
    return out

def apply_op(values, op, delim=",", prec=10, null="."):
    """values: list of strings (in order). If empty, caller handles null (but count ->0 etc). This returns string."""
    op=op.strip()
    if not values:
        if op=="count":
            return "0"
        if op=="count_distinct":
            return "0"
        return null
    # string based ops
    if op=="collapse":
        return delim.join(values)
    if op=="concat":
        return "".join(values)
    if op=="first":
        return values[0]
    if op=="last":
        return values[-1]
    if op=="count":
        return str(len(values))
    if op=="count_distinct":
        return str(len(set(values)))
    if op=="distinct":
        uniq=sorted(set(values))  # lexicographic string
        return delim.join(uniq)
    if op=="distinct_sort_num":
        # sort distinct numerically ascending, output original string representations? If duplicate numeric values have different strings "1.0" and "1", distinct by string or numeric? Likely they use set of strings then sort by numeric value of string.
        uniq=list(set(values))
        def keyfn(s):
            try: return float(s)
            except: return 0
        uniq.sort(key=keyfn)
        return delim.join(uniq)
    if op=="distinct_sort_num_desc":
        uniq=list(set(values))
        def keyfn(s):
            try: return float(s)
            except: return 0
        uniq.sort(key=keyfn, reverse=True)
        return delim.join(uniq)
    if op=="distinct_only":
        counts=Counter(values)
        uniq_sorted=sorted(set(values))
        # reproduce leading delimiter bug: delimiter before element if its index in sorted unique list >0, even if previous were skipped
        out=""
        for i, v in enumerate(uniq_sorted):
            if counts[v]==1:
                if i>0:
                    out+=delim
                out+=v
        return out
    if op in ("mode","antimode"):
        counts=Counter(values)
        uniq_sorted=sorted(set(values))
        if op=="mode":
            best=None; bestc=-1
            for v in uniq_sorted:
                c=counts[v]
                if c>bestc:
                    bestc=c; best=v
            return best
        else:
            best=None; bestc=None
            for v in uniq_sorted:
                c=counts[v]
                if bestc is None or c<bestc:
                    bestc=c; best=v
            return best
    if op in ("freqdesc","freqasc"):
        counts=Counter(values)
        items=list(counts.items()) # insertion order? but for sorting we use lexicographic tie
        # bedtools appears to start from map (lexicographic) then sort by freq
        items_sorted_lex=sorted(counts.items(), key=lambda kv: kv[0])
        if op=="freqdesc":
            items_sorted=sorted(items_sorted_lex, key=lambda kv: -kv[1])
        else:
            items_sorted=sorted(items_sorted_lex, key=lambda kv: kv[1])
        return delim.join(f"{v}:{c}" for v,c in items_sorted)
    # numeric ops
    nums=_to_floats(values)
    if nums is None:
        return null
    if op=="sum":
        return fmt_op_num(sum(nums), prec)
    if op=="min":
        return fmt_op_num(min(nums), prec)
    if op=="max":
        return fmt_op_num(max(nums), prec)
    if op=="absmin":
        # element with smallest absolute value, return its absolute value
        m=min(nums, key=lambda x: abs(x))
        return fmt_op_num(abs(m), prec)
    if op=="absmax":
        m=max(nums, key=lambda x: abs(x))
        return fmt_op_num(abs(m), prec)
    if op=="mean":
        return fmt_op_num(sum(nums)/len(nums), prec)
    if op=="median":
        s=sorted(nums); n=len(s)
        if n%2==1:
