# BGZF writing
BGZF_EOF = bytes([31,139,8,4,0,0,0,0,0,255,6,0,66,67,2,0,27,0,3,0,0,0,0,0,0,0,0,0])
def bgzf_block(data, level=6):
    # data uncompressed chunk < 64k
    comp=zlib.compressobj(level, zlib.DEFLATED, -15)
    cdata=comp.compress(data)+comp.flush()
    bsize=18+len(cdata)+8
    header=struct.pack("<BBBBIBBH",31,139,8,4,0,0,255,6) # wait need correct packing below manually
    # Build manually: ID1 ID2 CM FLG MTIME(4) XFL OS XLEN(2)
    header = b'\x1f\x8b\x08\x04' + struct.pack("<I",0) + b'\x00\xff' + struct.pack("<H",6)
    extra = b'BC' + struct.pack("<H",2) + struct.pack("<H",bsize-1)
    crc=zlib.crc32(data) & 0xffffffff
    trailer=struct.pack("<II",crc, len(data) & 0xffffffff)
    return header+extra+cdata+trailer

def write_bgzf(out_bytes, level=6):
    # split into chunks; htslib uses approx 65280? Use 0xff00? For small data one block.
    res=b""
    if len(out_bytes)==0:
        return BGZF_EOF
    chunk_size=65280-256  # leave room? htslib block length threshold ~ 64k compressed. Use 60000 to be safe
    # Actually to match htslib for small files, one block is fine regardless chunk.
    for i in range(0,len(out_bytes),chunk_size):
        res+=bgzf_block(out_bytes[i:i+chunk_size], level=level)
    res+=BGZF_EOF
    return res

def make_bam_bytes(header_text, refs, raw_blocks):
    # refs list (name,len)
    out=b"BAM\x01"
    ht=header_text.encode()
    out+=struct.pack("<i",len(ht))+ht
    out+=struct.pack("<i",len(refs))
    for name,length in refs:
        nb=name.encode()+b"\x00"
        out+=struct.pack("<i",len(nb))+nb+struct.pack("<i",length)
    for rb in raw_blocks:
        out+=struct.pack("<i",len(rb))+rb
    return out

