        raw_block=data[block_start:block_start+block_size]
        off=block_start+block_size
        aln=BamAlignment()
        aln.refID=refID; aln.pos=pos; aln.bin=binv; aln.mapq=mapq; aln.flag=flag; aln.l_seq=l_seq; aln.next_refID=next_refID; aln.next_pos=next_pos; aln.tlen=tlen; aln.read_name=read_name; aln.cigar=cigar; aln.seq=seq; aln.qual=qual; aln.aux=aux; aln.raw_block=raw_block; aln.order=order
