def sam_record_to_record(fields, order):
    # SAM fields: qname flag rname pos mapq cigar rnext pnext tlen seq qual [tags]
    if len(fields)<11:
        return None
    try:
        flag=int(fields[1]); pos1=int(fields[3]); mapq=int(fields[4])
    except:
        return None
    chrom=fields[2]; pos=pos1-1 if pos1>0 else 0
    cigar_str=fields[5]
    cigar=[]
    if cigar_str!="*":
        import re
        for length,opchar in re.findall(r'(\d+)([MIDNSHP=X])',cigar_str):
            cigar.append((int(length), CIGAR_OPS.index(opchar)))
    aln=BamAlignment(); aln.flag=flag; aln.read_name=fields[0]; aln.pos=pos; aln.mapq=mapq; aln.cigar=cigar; aln.seq=fields[9] if fields[9]!="*" else ""; aln.qual=fields[10] if fields[10]!="*" else None; aln.l_seq=len(aln.seq); aln.aux=[]; aln.raw_block=None; aln.order=order; aln.refID=0; aln.next_refID=-1; aln.next_pos=-1; aln.tlen=int(fields[8]) if len(fields)>8 else 0
    aln.chrom=chrom; aln.start=pos; aln.end=compute_ref_end(pos,cigar); aln.strand="-" if flag&0x10 else "+"; aln.blocks=compute_blocks(pos,cigar,(3,)); aln.blocks_ND=compute_blocks(pos,cigar,(3,2))
    # aux tags SAM format TAG:TYPE:VALUE
    for tf in fields[11:]:
        parts=tf.split(":",2)
        if len(parts)==3:
            tag,typ,valstr=parts
            if typ in ("i","I"):
                try: val=int(valstr)
                except: val=valstr
            elif typ=="f":
                try: val=float(valstr)
                except: val=valstr
            else:
                val=valstr
            aln.aux.append((tag,typ,val))
