    fields_bed=[chrom,str(pos),str(aln.end),fields[0],str(mapq),aln.strand,str(pos),str(aln.end),"0,0,0",str(len(blocks)),"".join(f"{e-s}," for s,e in blocks),"".join(f"{s-pos}," for s,e in blocks)]
