# BGZF writing
BGZF_EOF = bytes([31,139,8,4,0,0,0,0,0,255,6,0,66,67,2,0,27,0,3,0,0,0,0,0,0,0,0,0])
def bgzf_block(data, level=6):
    # data uncompressed chunk < 64k
    comp=zlib.compressobj(level, zlib.DEFLATED, -15)
    cdata=comp.compress(data)+comp.flush()
    bsize=18+len(cdata)+8
    header=struct.pack("<BBBBIBBH",31,139,8,4,0,0,255,6) # wait need correct packing below manually
    # Build manually: ID1 ID2 CM FLG MTIME(4) XFL OS XLEN(2)
    header = b'\x1f\x8b\x08\x04' + struct.pack("<I",0) + b'\x00\xff' + struct.pack("<H",6)
    extra = b'BC' + struct.pack("<H",2) + struct.pack("<H",bsize-1)
    crc=zlib.crc32(data) & 0xffffffff
    trailer=struct.pack("<II",crc, len(data) & 0xffffffff)
    return header+extra+cdata+trailer

def write_bgzf(out_bytes, level=6):
    # split into chunks; htslib uses approx 65280? Use 0xff00? For small data one block.
    res=b""
    if len(out_bytes)==0:
        return BGZF_EOF
    chunk_size=65280-256  # leave room? htslib block length threshold ~ 64k compressed. Use 60000 to be safe
    # Actually to match htslib for small files, one block is fine regardless chunk.
    for i in range(0,len(out_bytes),chunk_size):
        res+=bgzf_block(out_bytes[i:i+chunk_size], level=level)
    res+=BGZF_EOF
    return res

def make_bam_bytes(header_text, refs, raw_blocks):
    # refs list (name,len)
    out=b"BAM\x01"
    ht=header_text.encode()
    out+=struct.pack("<i",len(ht))+ht
    out+=struct.pack("<i",len(refs))
    for name,length in refs:
        nb=name.encode()+b"\x00"
        out+=struct.pack("<i",len(nb))+nb+struct.pack("<i",length)
    for rb in raw_blocks:
        out+=struct.pack("<i",len(rb))+rb
    return out

def write_bam_output(header_text, refs, records, ubam=False, out_buffer=None):
    raw_blocks=[]
    for r in records:
        if r.bam is not None and r.bam.raw_block is not None:
            raw_blocks.append(r.bam.raw_block)
        else:
            # build from aln/record
            raw_blocks.append(build_bam_block_from_record(r, refs))
    bam_bytes=make_bam_bytes(header_text, refs, raw_blocks)
    level=0 if ubam else 6
    # Note: reference merged tool -ubam file size same as compressed for tiny? Their ubam still bgzf (?) level 0.
    bgzf=write_bgzf(bam_bytes, level=level)
    if out_buffer is None:
        sys.stdout.buffer.write(bgzf)
    else:
        out_buffer.write(bgzf)
    return bgzf

def build_bam_block(refID,pos,mapq,flag,read_name,cigar,seq="",qual=None,next_refID=-1,next_pos=-1,tlen=0,aux=None,end_for_bin=None):
    if end_for_bin is None:
        end_for_bin=compute_ref_end(pos,cigar)
    binv=reg2bin(pos,end_for_bin) if refID>=0 and pos>=0 else 0
    # For unmapped ??? bin 0
    l_read_name=len(read_name.encode())+1
    bin_mq_nl=(binv<<16)|(mapq<<8)|l_read_name
    flag_nc=(flag<<16)|len(cigar)
    l_seq=len(seq)
    core=struct.pack("<iiIIiiii",refID,pos,bin_mq_nl,flag_nc,l_seq,next_refID,next_pos,tlen)
    out=core+read_name.encode()+b"\x00"
    for l,o in cigar:
        out+=struct.pack("<I",(l<<4)|o)
    # seq packed
    seq_packed=b""
    for i in range(0,l_seq,2):
        high=SEQ_CODES.find(seq[i].upper()) if i<l_seq else 0
        if high<0: high=15
        low=0
        if i+1<l_seq:
            low=SEQ_CODES.find(seq[i+1].upper())
            if low<0: low=15
        seq_packed+=bytes([(high<<4)|low])
    out+=seq_packed
    if qual is None:
        if l_seq>0:
            out+=b"\xff"*l_seq
    else:
        out+=bytes([max(0,ord(c)-33) for c in qual[:l_seq].ljust(l_seq,"!")])
    # aux
    if aux:
        for tag,typ,val in aux:
            out+=tag.encode()+typ.encode()
            if typ=='A': out+=val.encode()[:1] if isinstance(val,str) else bytes([val])
            elif typ=='c': out+=struct.pack("<b",val)
            elif typ=='C': out+=struct.pack("<B",val)
            elif typ=='s': out+=struct.pack("<h",val)
            elif typ=='S': out+=struct.pack("<H",val)
            elif typ=='i': out+=struct.pack("<i",val)
            elif typ=='I': out+=struct.pack("<I",val)
            elif typ=='f': out+=struct.pack("<f",val)
            elif typ in ('Z','H'): out+=str(val).encode()+b"\x00"
            elif typ=='B':
                sub,vals=val
                out+=sub.encode()+struct.pack("<i",len(vals))
                fmt_map={'c':'b','C':'B','s':'h','S':'H','i':'i','I':'I','f':'f'}
                for v in vals: out+=struct.pack("<"+fmt_map[sub],v)
    return out

def build_bam_block_from_record(rec, refs):
    ref_map={name:i for i,(name,l) in enumerate(refs)}
    refID=ref_map.get(rec.chrom,-1)
    if rec.bam is not None:
        aln=rec.bam
        return build_bam_block(aln.refID if aln.refID>=0 else refID, aln.pos, aln.mapq, aln.flag, aln.read_name, aln.cigar, aln.seq, aln.qual, aln.next_refID, aln.next_pos, aln.tlen, aln.aux, end_for_bin=aln.end)
    cigar=[(rec.length(),0)] if rec.length()>0 else []
    flag=16 if rec.strand=="-" else 0
    mapq=255
    name=rec.name if rec.name!="." else ""
    return build_bam_block(refID, rec.start, mapq, flag, name, cigar, "", None, -1,-1,0, None, end_for_bin=rec.end)

