import sys
from helpdata import HELP
from util import BedError

NEW_TOOLS = {"intersect","closest","coverage","map","merge","complement","subtract","sample","spacing","jaccard","fisher","summary"}
OLD_NOLEAD = {"getfasta","maskfasta","nuc"}
GROUPBY_LIKE = {"groupby"}
IGNORE_UNKNOWN = {"multiinter","unionbedg"}

def get_variant(tool, variant):
    e=HELP[tool][variant]
    return e['rc'], e['out'], e['err']

def emit_variant(tool, variant):
    rc,out,err=get_variant(tool,variant)
    if out: sys.stdout.write(out)
    if err: sys.stderr.write(err)
    return rc

def h_text(tool):
    rc,out,err=get_variant(tool,'h')
    return err if err else out

def usage_new_error(tool, messages):
    """Raise BedError with text = h usage + suffix errors. Messages are raw strings without stars (e.g. 'No input file given. Exiting.')"""
    txt=h_text(tool)
    # h_text typically ends with \n\n\n\n ; observed suffix preceded by an extra \n making 5? Check difference: none = h + '\n***** ERROR...' ? Let's compute dynamically in code? HELP none vs h for tools where none is h+single error - we can infer separator by comparing.
    # We determine separator as text between h prefix and error in none variant if none startswith h.
    sep="\n"
    try:
        rc,out,err=get_variant(tool,'none')
        full=err if err else out
        if full.startswith(txt) and len(full)>len(txt):
            rest=full[len(txt):]
            # rest begins maybe \n*****...
            if rest.startswith("\n*****"):
                sep="\n"
            elif rest.startswith("*****"):
                sep=""
    except Exception:
        pass
    suffix=""
    for m in messages:
        suffix+=f"{sep}***** ERROR: {m} *****\n" if suffix=="" else f"***** ERROR: {m} *****\n"
        sep=""
    raise BedError(txt+suffix,1)

def usage_old_error(tool, unknowns=None, validation=None):
    """Old framework: prefixes + validation + usage(h)
    unknowns: list of tokens
    validation: list of raw message strings to be formatted as \n*****\n*****ERROR: {msg} \n*****\n (note trailing space preserved if msg includes)
    But some validation errors elsewhere have different formatting; callers may pass preformatted validation_blocks instead.
    """
    txt=h_text(tool)
    prefix=""
    lead="" if tool in OLD_NOLEAD else "\n"
    for u in (unknowns or []):
        prefix+=f"{lead}*****ERROR: Unrecognized parameter: {u} *****\n\n"
        lead="\n" if tool not in OLD_NOLEAD else ""
        # For OLD_NOLEAD tools multiple unknowns: observed "*****... \n\n*****..." (no leading each) so lead remains ""
        # For lead tools: each starts with \n
    if validation:
        for msg in validation:
            if msg.startswith("\n*****") or msg.startswith("*****"):
                prefix+=msg
            else:
                # msg should include trailing space if reference has it; callers include exact string inside
                prefix+=f"\n*****\n*****ERROR: {msg}\n*****\n"
    raise BedError(prefix+txt,1)

def old_validation_block(msg):
    # msg exact including e.g. "Need -a and -b files. " (trailing space)
    return f"\n*****\n*****ERROR: {msg}\n*****\n"

def check_unknown(tool, unknown, argv=None):
    if not unknown:
        return
    if tool in IGNORE_UNKNOWN:
        return
    if tool in GROUPBY_LIKE:
        # just usage
        raise BedError(h_text(tool),1)
    if tool in NEW_TOOLS:
        usage_new_error(tool, [f"Unrecognized parameter: {u}" for u in unknown])
    elif tool=="makewindows":
        # old prefix despite help==h
        usage_old_error(tool, unknowns=unknown)
    else:
        usage_old_error(tool, unknowns=unknown)

def missing_arg_error(tool, missing):
    if not missing:
        return
    # new tools message pattern for -i etc is specific; generic:
    if tool in NEW_TOOLS:
        msgs=[]
        for m in missing:
            if m=="-i":
                msgs.append("-i option given, but no input file specified.")
            elif m=="-a":
                msgs.append("-a option given, but no input file specified.")
            elif m=="-b":
                msgs.append("-b option given, but no input file specified.")
            else:
                msgs.append(f"{m} option given, but no input file specified.")
        usage_new_error(tool, msgs)
    elif tool in GROUPBY_LIKE:
        raise BedError(h_text(tool),1)
    else:
        # old tools often treat next token missing as unrecognized? We'll output old prefix for the option
        usage_old_error(tool, unknowns=missing)

PYEOF
