        if full.startswith(txt) and len(full)>len(txt):
            rest=full[len(txt):]
            # rest begins maybe \n*****...
            if rest.startswith("\n*****"):
                sep="\n"
            elif rest.startswith("*****"):
                sep=""
    except Exception:
        pass
    suffix=""
