    if not unknown:
        return
    if tool in IGNORE_UNKNOWN:
        return
    if tool in GROUPBY_LIKE:
        # just usage
        raise BedError(h_text(tool),1)
    if tool in NEW_TOOLS:
        usage_new_error(tool, [f"Unrecognized parameter: {u}" for u in unknown])
    elif tool=="makewindows":
        # old prefix despite help==h
        usage_old_error(tool, unknowns=unknown)
    else:
        usage_old_error(tool, unknowns=unknown)

def missing_arg_error(tool, missing):
    if not missing:
        return
    # new tools message pattern for -i etc is specific; generic:
    if tool in NEW_TOOLS:
        msgs=[]
        for m in missing:
            if m=="-i":
                msgs.append("-i option given, but no input file specified.")
            elif m=="-a":
                msgs.append("-a option given, but no input file specified.")
            elif m=="-b":
                msgs.append("-b option given, but no input file specified.")
            else:
                msgs.append(f"{m} option given, but no input file specified.")
        usage_new_error(tool, msgs)
    elif tool in GROUPBY_LIKE:
        raise BedError(h_text(tool),1)
    else:
        # old tools often treat next token missing as unrecognized? We'll output old prefix for the option
        usage_old_error(tool, unknowns=missing)

