from errhelp import *

NEW_COMMON_FLAGS = ["-split","-sorted","-nonamecheck","-bed","-header","-nobuf"]
NEW_COMMON_ONES = ["-iobuf","-g"]

def get_overlap_spec(opts):
    f_spec = opts.get("-f") is not None
    F_spec = opts.get("-F") is not None
    f_val = parse_float(opts.get("-f"), 1e-9) if f_spec else 1e-9
    F_val = parse_float(opts.get("-F"), 1e-9) if F_spec else 1e-9
    # If parse fails? bedtools validation would... ignore
    return OverlapSpec(f=f_val,F=F_val,f_spec=f_spec,F_spec=F_spec,r=bool(opts.get("-r")),e=bool(opts.get("-e")),s=bool(opts.get("-s")),S=bool(opts.get("-S")),split=bool(opts.get("-split")))

def print_header(info, opts, out=sys.stdout):
    if opts.get("-header"):
        for h in info.header:
            out.write(h+"\n")

def format_record_line(rec, mode="original"):
    # For BAM records as query in new tools, fields are bed12
    return rec.to_line()

def format_b_record_line(rec):
    if rec.fmt=="bam":
        # actual B record printed as BED6
        return "\t".join(rec.extra.get('bed6_fields', rec.fields[:6]))
    return rec.to_line()

def record_intersect_line(a_rec, b_rec):
    # default intersect output: A fields with start/end trimmed to overlap (based on overall span, not blocks)
    # For VCF A, fields unchanged (to_line) as observed
    if a_rec.fmt=="vcf":
        return a_rec.to_line()
    # For zero-length A? Observed chr1 150 150 unchanged (overlap segment would be that)
    s=max(a_rec.start,b_rec.start); e=min(a_rec.end,b_rec.end)
    # If overlap due zero-length expansion, s/e may be weird inverted? e.g A zero vs B adjacent below: s=100 e=100 -> okay. A normal vs B zero at boundary: s=100 e=100 -> (?) output default would be chr 100 100? Let's adopt s,e clamping: if e<s, set e=s (=?) Need check later
    if e < s:
        # use effective overlap interval intersect of first overlapping pair?
        # find overlapping effective pair
        for sa,ea in a_rec.effective_intervals(False):
            for sb,eb in b_rec.effective_intervals(False):
                if min(ea,eb)>max(sa,sb):
                    s=max(sa,sb); e=min(ea,eb)
                    # But for printing BED, if A zero expanded interval, original output earlier was 150 150 not expanded 149-151 intersect; so keep original a coord if A zero
                    if a_rec.zero:
                        s=a_rec.start; e=a_rec.end
                    break
    if a_rec.zero:
        s=a_rec.start; e=a_rec.end
    # copy
    new=a_rec.copy_with_coords(s,e)
    return new.to_line()

def validate_prec(tool, opts):
    if opts.get("-prec") is not None:
        try:
            v=int(opts["-prec"])
            if v<=0: raise ValueError()
        except:
            if tool in NEW_TOOLS or tool in ("map","merge"):
                usage_new_error(tool, ["-prec must be followed by a positive integer. Exiting."])
            else:
                raise BedError(h_text(tool),1)
        return v
    return 10

def check_bam_bin_error(b_records):
    # If any B record is zero-length at 0 (effective start -1) and using non-sorted binning, reference errors.
    # Only apply in some tools? We'll call selectively for intersect default.
    for r in b_records:
        if r.zero and r.start==0:
            raise BedError("ERROR: Received illegal bin number -1 from getBin call.\nMaximum values is: 2396745\nThis typically means that your coordinates are\nnegative or too large to represent in the data\nstructure bedtools uses to find intersections.ERROR: Unable to add record to tree.\n")

def sort_hits_by_order(hits):
    hits.sort(key=lambda t: t[0].order if isinstance(t,tuple) else t.order)
    return hits

def parse_names(opts, num_b):
    names=opts.get("-names") or []
    return names

def db_label(idx, opts, b_files):
    # idx 0-based
    if opts.get("-names"):
        names=opts["-names"]
        if idx < len(names):
            return names[idx]
    if opts.get("-filenames"):
        return b_files[idx]
    return str(idx+1)

def load_two_files(tool, opts, style="new"):
    a_path=opts.get("-a")
    b_paths=opts.get("-b") or []
    a_recs,a_info=read_records(a_path, style=style)
    b_data=[]
    for bp in b_paths:
        recs,info=read_records(bp, style=style)
        for r in recs: r.file_id=len(b_data)
        b_data.append((recs,info))
    return a_recs,a_info,b_data

def is_bam_file(info):
    return getattr(info,"is_bam",False)

def write_bam_filtered(a_info, keep_records, opts):
    # keep_records are A BAM records (original)
    from bam import write_bam_output
    header_text=getattr(a_info,"bam_header_text","")
    refs=a_info.refs
    ubam=bool(opts.get("-ubam"))
    write_bam_output(header_text, refs, keep_records, ubam=ubam)

