    for r in records:
        if r.chrom!=prev_chrom:
            if r.chrom in seen:
                raise BedError(f"Error: Sorted input specified, but the file {path} has the following out of order record\n{r.to_line()}\n")
            seen.add(r.chrom); prev_chrom=r.chrom; prev_start=r.start
        else:
            if r.start < prev_start:
                raise BedError(f"Error: Sorted input specified, but the file {path} has the following out of order record\n{r.to_line()}\n")
            prev_start=r.start

