    blocks=[] # list of (chrom, first_record)
    prev=None
    for r in records:
        if r.chrom!=prev:
            blocks.append((r.chrom,r)); prev=r.chrom
    return blocks

def check_sorted_consistency(record_lists, paths, genome=None):
    # individual first
    for recs,path in zip(record_lists,paths):
        check_sorted_individual(recs,path)
    # genome order check individual if genome provided: if a record chrom index goes backwards relative to genome
    if genome is not None:
        order={c:i for i,c in enumerate(genome.keys())}
        # If a file's chromosome order differs from genome, the first backward block is different sort order?
        # Reference for complement used that message; for sorted sweep tools, genome gives expected order so block sequence must be increasing genome idx.
        for recs,path in zip(record_lists,paths):
            prev_idx=-1
            for chrom,first in _blocks(recs):
                if chrom in order:
                    if order[chrom] < prev_idx:
                        raise BedError(f"ERROR: chromosome sort ordering for file {path} is inconsistent with other files. Record was:\n{first.to_line()}\n")
                    prev_idx=order[chrom]
        # also cross file consistency automatically if both follow genome
        return
    # simulate sweep
    blocks_list=[_blocks(recs) for recs in record_lists]
    idx=[0]*len(blocks_list)
    visited_order=[]
    visited=set()
    while True:
        heads=[]
        for i,bl in enumerate(blocks_list):
            if idx[i]<len(bl):
                heads.append((bl[idx[i]][0],i))
        if not heads:
            break
        # choose lexicographically smallest head chrom among not visited? If any head chrom already visited -> its file is ebhind: but that will be chosen as smallest maybe and flagged when trying to select.
        # Check if any head is visited: note heads that we've just advanced to after finishing previous chrom may be visited.
        # Determine next chrom: smallest lexicographic head
        next_chrom=min(c for c,i in heads)
        if next_chrom in visited:
            # find file(s) with that head, error on first such in list order (record_lists order is A then B as given by caller; caller may order to ???)
            for c,i in heads:
                if c==next_chrom:
                    rec=blocks_list[i][idx[i]][1]
                    raise BedError(f"ERROR: chromosome sort ordering for file {paths[i]} is inconsistent with other files. Record was:\n{rec.to_line()}\n")
        visited.add(next_chrom); visited_order.append(next_chrom)
        for i,bl in enumerate(blocks_list):
            if idx[i]<len(bl) and bl[idx[i]][0]==next_chrom:
                idx[i]+=1
    # done
