import sys, os, math
from util import *
from records import *
from errhelp import *
from common import *
from sortedcheck import *
from ops import *

# ---------- intersect ----------
def tool_intersect(argv):
    tool="intersect"
    parser=ArgParser(
        flags=["-wa","-wb","-loj","-wo","-wao","-u","-c","-C","-v","-ubam","-s","-S","-r","-e","-filenames","-sortout"]+NEW_COMMON_FLAGS,
        ones=["-a","-f","-F"]+NEW_COMMON_ONES,
        multis=["-b","-names"],
    )
    opts,unknown,missing=parser.parse(argv)
    # validations in approximated order
    # missing specific
    if "-a" in missing:
        usage_new_error(tool, ["-a option given, but no query file specified."])
    if "-b" in missing:
        usage_new_error(tool, ["-b option given, but no database file specified."])
    if "-names" in missing:
        usage_new_error(tool, ["-b option given, but no database names specified."])
    # If -a or -b option appears in argv but parser consumed weird?? missing handled
    a_path=opts.get("-a"); b_paths=opts.get("-b") or []
    if a_path is None and not b_paths:
        # could be unknown etc - reference gives No input given priority
        usage_new_error(tool, ["No input file given. Exiting."])
    if a_path is None or not b_paths:
        usage_new_error(tool, ["query and database files not specified."])
    # fraction validations before unknown? If -f missing at end, unknown-like - reference gave Unrecognized -f. Our missing includes -f
    if "-f" in missing or "-F" in missing:
        # treat as unrecognized
        usage_new_error(tool, [f"Unrecognized parameter: {m}" for m in missing if m in ("-f","-F")])
    # validate f/F range
    for optname in ("-f","-F"):
        if opts.get(optname) is not None:
            v=parse_float(opts[optname],0)
            if v is None or not (0 < v <= 1.0):
                usage_new_error(tool, [f"{optname} must be in the range (0.0, 1.0]."])
    # conflict checks (some)
    if opts.get("-u") and opts.get("-v"):
        usage_new_error(tool, ["request either -u for anyHit OR -v for noHit, not both."])
    if opts.get("-c") and opts.get("-u"):
        usage_new_error(tool, ["request either -c for writeCount OR -u for anyHit, not both."])
    if opts.get("-u") and (opts.get("-wo") or opts.get("-wao")):
        usage_new_error(tool, ["request either -u for anyHit OR -wo for writeOverlap, not both."])
    if opts.get("-c") and (opts.get("-wo") or opts.get("-wao")):
        usage_new_error(tool, ["request either -c for writeCount OR -wo for writeOverlap, not both."])
    # unknown after major validations
    if unknown:
        check_unknown(tool, unknown)
    # also other missing as unrecognized
    other_missing=[m for m in missing if m not in ("-a","-b","-names","-f","-F")]
    if other_missing:
        usage_new_error(tool, [f"Unrecognized parameter: {m}" for m in other_missing])
    spec=get_overlap_spec(opts)
    # Load files
    a_recs,a_info=read_records(a_path, style="new")
    # BAM specific validations / warnings
    is_bam_a=is_bam_file(a_info)
    bed_out=bool(opts.get("-bed"))
    if is_bam_a and not bed_out:
        if opts.get("-wo") or opts.get("-wao"):
            usage_new_error(tool, ["writeAllOverlap option is not valid with BAM query input, unless bed output is specified with -bed option."])
        if opts.get("-c"):
            usage_new_error(tool, ["writeCount option is not valid with BAM query input, unless bed output is specified with -bed option."])
    # sorted check later after loading Bs
    b_data=[]
    all_b_recs=[]
    for idx,bp in enumerate(b_paths):
        recs,info=read_records(bp, style="new")
        for r in recs: r.file_id=idx
        b_data.append((recs,info,make_db(recs)))
        all_b_recs.extend(recs)
    if opts.get("-sorted"):
        genome=None
        if opts.get("-g"):
            genome=read_genome(opts["-g"], style="new")
        check_sorted_consistency([a_recs]+[recs for recs,info,db in b_data], [a_path]+b_paths, genome=genome)
    else:
        # bin error for zero at 0 B records (only non-sorted?)
        check_bam_bin_error(all_b_recs)
    # header / warnings for BAM
    if is_bam_a and opts.get("-header"):
        sys.stderr.write("\n*****\n*****WARNING: -header option is not valid for BAM input.\n*****\n")
    if is_bam_a and not bed_out:
        if opts.get("-wb") or opts.get("-loj"):
            sys.stderr.write("\n*****\n*****WARNING: -wb and -loj are ignored with bam input, unless bed output is specified with -bed option.\n*****\n")
        # BAM filtered output
        keep=[]
        for a in a_recs:
            # skip unmapped? They would have no hits; if -v they'd be kept? samtools view? Assume include logic by hits
            total_hits=0
            for recs,info,db in b_data:
                hits=db.find(a,spec)
                total_hits+=len(hits)
            if opts.get("-v"):
                if total_hits==0: keep.append(a)
            elif opts.get("-loj") or opts.get("-C"):
                keep.append(a)
            else:
                if total_hits>0: keep.append(a)
        write_bam_filtered(a_info, keep, opts)
        return 0
    # text output
    print_header(a_info, opts)
    multi=len(b_data)>1
    # Mode decision (single modes priority approximate)
    mode="default"
    if opts.get("-loj"):
        mode="loj"
    elif opts.get("-wao"):
        mode="wao"
    elif opts.get("-wo"):
        mode="wo"
    elif opts.get("-u") and not opts.get("-C"):
        mode="u"
    elif opts.get("-c"):
        mode="c"
    elif opts.get("-C"):
        # Special if -u also present, fall to hybrid? ignore
        mode="C"
    elif opts.get("-v"):
        mode="v"
    # For -v combined with wo/wao/loj observed -v wins in combos above (except errors). But single mode fine.
    if opts.get("-v") and (opts.get("-wo") or opts.get("-wao") or opts.get("-loj")) and not (opts.get("-u") or opts.get("-c")):
        mode="v"
    wa=bool(opts.get("-wa")); wb=bool(opts.get("-wb"))
    out=[]
    for a in a_recs:
        # collect hits per DB
        per_db=[]
        all_hits=[] # list of (b,ov,db_idx)
        for db_idx,(recs,info,db) in enumerate(b_data):
            hits=db.find(a,spec)
            per_db.append(hits)
            for b,ov in hits:
                all_hits.append((b,ov,db_idx))
        if opts.get("-sortout"):
            all_hits_sorted=sorted(all_hits, key=lambda t:(t[0].chrom,t[0].start,t[0].end,t[2],t[0].order))
        else:
            all_hits_sorted=all_hits
        if mode=="u":
            if all_hits:
                out.append(a.to_line()+"\n")
        elif mode=="v":
            if not all_hits:
                out.append(a.to_line()+"\n")
        elif mode=="c":
            out.append(f"{a.to_line()}\t{len(all_hits)}\n")
        elif mode=="C":
            if multi:
                for db_idx,hits in enumerate(per_db):
                    # label? -C output observed: A fields + db_id (1-based) + count . If -names used, label presumably name instead of id? Probe later
                    label=db_label(db_idx,opts,b_paths)
                    out.append(f"{a.to_line()}\t{label}\t{len(hits)}\n")
            else:
                # single DB -C behaves like -c ? Observed earlier -u + -C gave weird but single -C?
                # Test assumed: likely outputs A + count (no file id) if single? We'll check later
                out.append(f"{a.to_line()}\t{len(all_hits)}\n")
        elif mode=="loj":
            if all_hits:
                for b,ov,db_idx in all_hits_sorted:
                    line=a.to_line()
                    if multi:
                        line+="\t"+db_label(db_idx,opts,b_paths)
                    line+="\t"+format_b_record_line(b)
                    # wao+loj hybrid had overlap on null only; ignore
                    out.append(line+"\n")
            else:
                # null B: if multi? For multiple databases loj with no hits: need probe. Assume one null per (?) Use first B info? If multi, maybe one line per DB with label? We'll handle simple: if multi, one line per db with label + null of that db
                if multi:
                    for db_idx,(recs,info,db) in enumerate(b_data):
                        line=a.to_line()+"\t"+db_label(db_idx,opts,b_paths)+"\t"+info.null_line()
                        if opts.get("-wao"):
                            line+="\t0"
                        out.append(line+"\n")
                else:
                    info=b_data[0][1] if b_data else FileInfo("stdin")
                    line=a.to_line()+"\t"+info.null_line()
                    if opts.get("-wao"):
                        line+="\t0"
                    out.append(line+"\n")
        elif mode in ("wo","wao"):
            if all_hits:
                for b,ov,db_idx in all_hits_sorted:
                    line=a.to_line()
                    if multi:
                        line+="\t"+db_label(db_idx,opts,b_paths)
                    line+="\t"+format_b_record_line(b)
                    reported=a.overlap_len_reported(b,spec.split)
                    line+=f"\t{reported}"
                    out.append(line+"\n")
            elif mode=="wao":
                if multi:
                    for db_idx,(recs,info,db) in enumerate(b_data):
                        line=a.to_line()+"\t"+db_label(db_idx,opts,b_paths)+"\t"+info.null_line()+"\t0"
                        out.append(line+"\n")
                else:
                    info=b_data[0][1] if b_data else FileInfo("stdin")
                    line=a.to_line()+"\t"+info.null_line()+"\t0"
                    out.append(line+"\n")
        else: # default
            for b,ov,db_idx in all_hits_sorted:
                if wa and wb:
                    line=a.to_line()
                    if multi: line+="\t"+db_label(db_idx,opts,b_paths)
                    line+="\t"+format_b_record_line(b)
                    out.append(line+"\n")
                elif wa:
                    out.append(a.to_line()+"\n")
                elif wb:
                    # A trimmed to intersect, + (label) + B
                    line=record_intersect_line(a,b)
                    if multi: line+="\t"+db_label(db_idx,opts,b_paths)
                    line+="\t"+format_b_record_line(b)
                    out.append(line+"\n")
                else:
                    out.append(record_intersect_line(a,b)+"\n")
    sys.stdout.write("".join(out))
    return 0

PYEOF
"}

