import sys, os
# Ensure modules in zipapp root are importable (they are top-level)
from util import BedError, VERSION
from helpdata import HELP
from errhelp import emit_variant

COMMANDS = "intersect window closest coverage map genomecov merge cluster complement shift subtract slop flank sort random shuffle sample spacing annotate multiinter unionbedg pairtobed pairtopair bamtobed bedtobam bamtofastq bedpetobam bed12tobed6 getfasta maskfasta nuc multicov tag jaccard reldist fisher overlap igv links makewindows groupby expand split summary".split()

# Command aliases (legacy names) - bedtools binary invoked as e.g. intersectBed via argv0 or subcommand? Our dispatch will handle some aliases.
ALIASES = {
    "intersectbed":"intersect","windowbed":"window","closestbed":"closest","coveragebed":"coverage","mapbed":"map","genomecoveragebed":"genomecov","mergbed":"merge","mergebed":"merge","clusterbed":"cluster","complementbed":"complement","shiftbed":"shift","subtractbed":"subtract","slopbed":"slop","flankbed":"flank","sortbed":"sort","randombed":"random","shufflebed":"shuffle","annotatebed":"annotate","multiintersectbed":"multiinter","unionbedgraphs":"unionbedg","pairtobed":"pairtobed","pairtopair":"pairtopair","bamtobed":"bamtobed","bedtobam":"bedtobam","bamtofastq":"bamtofastq","bedpetobam":"bedpetobam","bed12tobed6":"bed12tobed6","fastafrombed":"getfasta","maskfastafrombed":"maskfasta","nucbed":"nuc","linksbed":"links","bedtoigv":"igv","groupby":"groupby",
}

def main(argv=None):
    if argv is None:
        argv=sys.argv[1:]
    # Global --cram-ref handling: can appear before subcommand (and maybe after?) bedtools main parses it.
    # Format: bedtools --cram-ref <ref> <subcommand> ...  It sets env CRAM_REFERENCE ? Observed --cram-ref alone as first arg gives unrecognized command (because no subcommand? earlier we saw --cram-ref alone rc1 unrecognized, but with value+subcommand it worked to run intersect -h)
    # Implement: if first tokens are --cram-ref <val>, consume them, set env, continue. If --cram-ref is alone etc, fall through to unrecognized.
    if len(argv)>=3 and argv[0]=="--cram-ref":
        os.environ["CRAM_REFERENCE"]=argv[1]
        argv=argv[2:]
    elif len(argv)>=3 and argv[0]=="-cram-ref":
        os.environ["CRAM_REFERENCE"]=argv[1]
        argv=argv[2:]
    # Also maybe --cram-ref after subcommand? Tools may accept as unknown? Leave.
    prog_name=os.path.basename(sys.argv[0]) if sys.argv else ""
    # If executable invoked via symlink with tool name ? e.g. intersectBed - The original bedtools main checks argv[0]? Not sure. Handle if prog_name in aliases and argv first not a command
    # Only apply if prog_name is not 'executable' and not '__main__.py' etc and maps to a command
    if prog_name.lower() in ALIASES and (not argv or argv[0] not in COMMANDS):
        # But our built executable is named 'executable' in tests, so not triggered
        argv=[ALIASES[prog_name.lower()]]+argv
    if not argv:
        rc,out,err=(HELP["__main__"]["none"]['rc'], HELP["__main__"]["none"]['out'], HELP["__main__"]["none"]['err'])
        if out: sys.stdout.write(out)
        if err: sys.stderr.write(err)
        return rc
    first=argv[0]
    if first in ("--help","-h","-help","--h"):
        # main help to stdout rc0
        sys.stdout.write(HELP["__main__"]["help"]['out'])
        return 0
    if first in ("--version","-version"):
        sys.stdout.write(HELP["__main__"]["version"]['out'])
        return 0
    if first in ("--contact","-contact"):
        sys.stdout.write(HELP["__main__"]["contact"]['out'])
        return 0
    # Also -v? Check original: bedtools -v ??? We'll test later; for now if first == "-v" maybe version? Leave unrecognized if not.
    cmd=first
    # aliases for subcommands case sensitivity? bedtools commands are lower case exactly; intersectBed as subcommand maybe unrecognized in original? Test later.
    if cmd not in COMMANDS:
        # check if it is alias in lower case? Original likely unrecognized for e.g. "version" etc.
        sys.stderr.write(f"error: unrecognized command: {cmd}\n\n")
        return 1
    sub_argv=argv[1:]
    # Global cram-ref after subcommand? If sub_argv contains --cram-ref <val>, remove and set env (original main may parse before dispatching tools? In help General Parameters listed)
    # We'll scan for --cram-ref token in sub_argv and remove it+value
    if "--cram-ref" in sub_argv:
        idx=sub_argv.index("--cram-ref")
        if idx+1 < len(sub_argv):
            os.environ["CRAM_REFERENCE"]=sub_argv[idx+1]
            sub_argv=sub_argv[:idx]+sub_argv[idx+2:]
    # Help handling exact for -h anywhere, and --help for tools where help==h or split/multi special are handled per tool
    # split is special
    if cmd=="split":
        # delegate to tool which handles its own help/version
        pass
    elif "-h" in sub_argv:
        return emit_variant(cmd,"h")
    elif "--help" in sub_argv:
        # if help variant equals h variant for this tool, emit h; if tool is multiinter/unionbedg, ignore (do not emit)
        if cmd in ("multiinter","unionbedg"):
            # remove --help token(s) and continue
            sub_argv=[a for a in sub_argv if a!="--help"]
        elif HELP[cmd]["help"]==HELP[cmd]["h"]:
            return emit_variant(cmd,"h")
        elif sub_argv==["--help"]:
            return emit_variant(cmd,"help")
        # else: let tool handle --help as unknown parameter
    elif not sub_argv:
        # tools that read stdin (merge etc) should not static emit if they can function on stdin.
        # We'll let tool function decide, except tools where none variant is an error (they will replicate via validation)
        # But to guarantee exact for empty, some tools (links,igv) produce output on empty stdin - functional will handle.
        pass
    # dispatch
    try:
        return dispatch(cmd, sub_argv)
    except BedError as e:
        if e.msg:
            sys.stderr.write(e.msg)
        return e.code
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except:
            pass
        return 0
    except KeyboardInterrupt:
        return 1

def dispatch(cmd, argv):
    # import lazily
    if cmd=="intersect":
        from tools1 import tool_intersect; return tool_intersect(argv)
    # placeholders until implemented: emit none variant if no argv else ??? For now import all-in-one modules
    try:
        import tools_all
        func=getattr(tools_all, "tool_"+cmd, None)
        if func is not None:
            return func(argv)
    except ImportError:
        pass
    # fallback: if not implemented, show help
    return emit_variant(cmd,"h")

if __name__=="__main__":
    sys.exit(main())
