def validate_ops_and_cols(cols, ops_list, max_col, filename):
    # cols list ints, ops_list list strings before expansion
    # column range first
    for c in cols:
        if c < 1 or c > max_col:
            raise BedError(f"\n*****\n***** ERROR: Requested column {c}, but database file {filename} only has fields 1 - {max_col}.\n", 0)
    if not (len(cols)==1 or len(ops_list)==1 or len(cols)==len(ops_list)):
        raise BedError(f"\n*****\n***** ERROR: There are {len(cols)} columns given, but there are {len(ops_list)} operations.\n\tPlease provide either a single operation that will be applied to all listed columns, \n\ta single column to which all operations will be applied,\n\tor an operation for each column.\n", 0)
    from ops import VALID_OPS
    for op in ops_list:
        if op not in VALID_OPS:
            raise BedError(f"\n*****\n***** ERROR: {op} is not a valid operation. \n", 0)

def parse_op_args(opts, default_col=5):
    cols=[]
    if opts.get("-c") is not None:
        # -c may be like "5,4"
        for tok in str(opts["-c"]).split(","):
            tok=tok.strip()
            if tok=="": continue
            try: cols.append(int(tok))
            except: cols.append(0)
    else:
        cols=[default_col]
    ops_list=[]
    # groupby aliases -o / -ops already canonicalized to -o by parser aliases if provided
    if opts.get("-o") is not None:
        ops_list=[t.strip() for t in str(opts["-o"]).split(",") if t.strip()!=""]
    else:
        ops_list=["sum"]
    prec=10
    if opts.get("-prec") is not None:
        # validate elsewhere
        try: prec=int(opts["-prec"])
        except: prec=10
    delim=opts.get("-delim") if opts.get("-delim") is not None else ","
    null=opts.get("-null") if opts.get("-null") is not None else "."
    return cols, ops_list, prec, delim, null

def expanded_pairs(cols, ops_list):
    from ops import parse_cols_ops
    # reuse logic by constructing strings
    return parse_cols_ops(",".join(str(c) for c in cols), ",".join(ops_list))

