def _coverage_for_a(a, hits_records, spec):
    # hits_records: list of B records passing spec
    segments=[]
    subcount=0
    a_eff=a.effective_intervals(spec.split)
    if not a_eff:
        a_eff=[(a.start,a.end)]
    a_min=min(s for s,e in a_eff); a_max=max(e for s,e in a_eff)
    length=a_max-a_min
    for b in hits_records:
        b_eff=b.effective_intervals(spec.split)
        for sa,ea in a_eff:
            for sb,eb in b_eff:
                s=max(sa,sb); e=min(ea,eb)
                if e>s:
                    segments.append((s,e)); subcount+=1
    # sweep
    events={}
    for s,e in segments:
        events[s]=events.get(s,0)+1
        events[e]=events.get(e,0)-1
    # histogram depth->bases
    hist={}
    covered=0; sumdepth=0
    # iterate sorted unique points including a_min/a_max
    points=sorted(set([a_min,a_max]+list(events.keys())))
    # clamp points to domain
    points=[p for p in points if a_min <= p <= a_max]
    depth=0
    # need process in order: at point p, depth changes by events[p] for segment starting p.
    # Our events at start +1, at end -1, segment [p,next) depth after applying events at p.
    per_pos=None
    for i in range(len(points)-1):
        p=points[i]; np=points[i+1]
        depth+=events.get(p,0)
        if np>p:
            hist[depth]=hist.get(depth,0)+(np-p)
            if depth>0: covered+=(np-p)
            sumdepth+=depth*(np-p)
    # any gaps if a_eff blocks have internal gaps: points include segment points, but between blocks depth is currently tracking segments only (segments only inside blocks) so depth will be 0 in gaps correctly because segments end at block end.
    # However if a domain starts before first segment etc points includes a_min/a_max.
    if length==0:
        hist={0:0}
    return {
        "count": subcount,
        "covered": covered,
        "length": length,
        "frac": (covered/length if length else 0),
        "hist": hist,
        "sumdepth": sumdepth,
        "mean": (sumdepth/length if length else 0),
        "segments": segments,
        "a_min": a_min,
        "a_max": a_max,
    }

