# ---------- closest ----------
def _closest_distance(a,b,spec):
    # returns (unsigned, ref_sign, overlap_eff)
    ov=a.overlap_len_effective(b,spec.split)
    if ov>0:
        return 0,0,ov
    best=None; best_sign=0
    for sa,ea in a.effective_intervals(spec.split):
        for sb,eb in b.effective_intervals(spec.split):
            if eb<=sa:
                gap=sa-eb+1; sign=-1
            elif sb>=ea:
                gap=sb-ea+1; sign=1
            else:
                gap=0; sign=0
            if best is None or gap<best:
                best=gap; best_sign=sign
    return best,best_sign,ov

def tool_closest(argv):
    tool="closest"
    parser=ArgParser(flags=["-d","-io","-iu","-id","-fu","-fd","-N","-s","-S","-r","-e","-filenames","-sortout"]+NEW_COMMON_FLAGS, ones=["-a","-D","-t","-mdb","-k","-f","-F"]+NEW_COMMON_ONES, multis=["-b","-names"])
