    # custom closest validations: these errors have non-standard suffix formats. We'll construct whole stderr as h_text with adjustments.
    # Helper to make custom suffix exactly as observed:
    def custom_error(suffix):
        raise BedError(h_text(tool).rstrip("\n")+"\n\n\n"+suffix if False else h_text(tool)[:-1]+suffix,1) # placeholder overwritten below
    # Instead build from h_text: h_text ends with "E.g. none\t-1\t-1\n\n\n\n\n" (5? let's examine: h variant ends with that sequence plus). Observed -t error replaces one \n: "E.g... \n\n\n*****ERROR..."
    # We'll generate by taking h_text and trimming trailing newlines to have exactly 3 blank? Simpler: use captured structure: take h_text, strip trailing \n, then add "\n\n\n" + suffix for type A, and "\n\n\n\n" + block for type B.
    h=h_text(tool)
    # h ends with ...E.g. ...\n\n\n\n\n  (check via rstrip)
    h_core=h.rstrip("\n")
    if opts.get("-t") is not None and opts["-t"] not in ("all","first","last"):
        raise BedError(h_core+'\n\n\n*****ERROR: Request "all", "first", "last" for Tie Mode (-t)\n',1)
    if opts.get("-mdb") is not None and opts["-mdb"] not in ("each","all"):
        raise BedError(h_core+'\n\n\n*****ERROR: Request "each" or "last" for Multiple Database Mode (-mdb)\n',1)
    if opts.get("-D") is not None and opts["-D"] not in ("ref","a","b"):
        raise BedError(h_core+'\n\n\n*****ERROR: -D option must be followed with "ref", "a", or "b"\n',1)
    if (opts.get("-iu") or opts.get("-id")):
        if opts.get("-iu") and opts.get("-id"):
            raise BedError(h_core+'\n\n\n\n\n*****\n*****ERROR: Request either -iu OR -id, not both.\n*****\n\n',1)
        if opts.get("-D") is None:
            raise BedError(h_core+'\n\n\n\n\n*****\n*****ERROR: When requesting -iu or -id, you also need to specify -D.\n*****\n\n',1)
    if (opts.get("-fu") or opts.get("-fd")) and opts.get("-D") is None:
        raise BedError(h_core+'\n\n\n\n\n*****\n*****ERROR: When requesting -fu or -fd, you also need to specify -D.\n*****\n\n',1)
    if unknown: check_unknown(tool,unknown)
    other_missing=[m for m in missing if m not in ("-a","-b","-names","-f","-F","-k","-D","-t","-mdb")]
    if other_missing: usage_new_error(tool,[f"Unrecognized parameter: {m}" for m in other_missing])
