    is_bam_a=is_bam_file(a_info)
    if is_bam_a and not opts.get("-bed"):
        # header only BAM as observed
        from bam import write_bam_output
        write_bam_output(getattr(a_info,"bam_header_text",""), a_info.refs, [], ubam=False)
        return 0
    if is_bam_a and opts.get("-header"):
