    for a in a_recs:
        # Build candidate pools
        pools=[] # list of candidate lists to process independently if mdb each, or one pooled if all
        if mdb=="all" and multi:
            pools=[[]]
            for db_idx,(recs,info,db) in enumerate(b_data):
                cand=[]
                for b in db_candidates[db_idx].get(a.chrom,[]):
