        else:
            pools=[]
            for db_idx,(recs,info,db) in enumerate(b_data):
                cand=[]
                for b in db_candidates[db_idx].get(a.chrom,[]):
                    c=_closest_candidate(a,b,spec,opts)
                    if c is not None:
                        cand.append((c[0],c[1],c[2],db_idx))
                pools.append(cand)
        for pool_idx,candidates in enumerate(pools):
            # pool_idx corresponds to db_idx if mdb each, else 0 pooled
            # Apply iu/id/fu/fd filters based on signed distance
            def signed_of(cand):
                b,unsigned,ref_sign,db_idx=cand
                return _signed_distance(a,b,unsigned,ref_sign,opts)
            if opts.get("-iu"):
                candidates=[c for c in candidates if signed_of(c)>=0]
            if opts.get("-id"):
                candidates=[c for c in candidates if signed_of(c)<=0]
            if opts.get("-fu"):
                up=[c for c in candidates if signed_of(c)<0]
                if up: candidates=up
            elif opts.get("-fd"):
                down=[c for c in candidates if signed_of(c)>0]
                if down: candidates=down
            if not candidates:
                # null line
                if mdb=="all" and multi:
                    # Null format for pooled multi? Use "." label + first db null ? Probe later
                    info=b_data[0][1]
                    line=a.to_line()+"\t"+".\t"+info.null_line()
                elif multi:
                    db_idx=pool_idx
                    info=b_data[db_idx][1]
                    line=a.to_line()+"\t"+db_label(db_idx,opts,b_paths)+"\t"+info.null_line()
                    # Wait closest multi with a db having no hit on chrom: does it output label then null? Probe later; if label should be "." like intersect, this may differ. But for closest each DB needs a line per DB to indicate which.
                else:
                    info=b_data[0][1] if b_data else FileInfo("stdin")
                    line=a.to_line()+"\t"+info.null_line()
                if opts.get("-d") or opts.get("-D"):
                    line+="\t-1"
                out.append(line+"\n")
                continue
            # sort key and selection
            def sort_key(cand):
                b,unsigned,ref_sign,db_idx=cand
                signed=_signed_distance(a,b,unsigned,ref_sign,opts) if opts.get("-D") else ref_sign*unsigned
                if opts.get("-sortout"):
                    # sortout for closest multi: sort DB hits for each record by (?) chromosomal position
                    return (unsigned, b.chrom, b.start, b.end, db_idx, b.order)
                return (unsigned, signed, db_idx, b.order)
            selected=[]
            if tie=="all":
                sorted_cand=sorted(candidates, key=sort_key)
                if len(sorted_cand)<=k_val:
                    selected=sorted_cand
                else:
                    thresh=sorted_cand[k_val-1][1]
                    selected=[c for c in sorted_cand if c[1]<=thresh]
                    # Wait this selects all with unsigned <= thresh, equivalent to first k + ties at kth
            else:
                # collapse by unsigned distance
                by_dist={}
                for c in candidates:
                    d=c[1]
                    if d not in by_dist:
                        by_dist[d]=c
                    else:
                        # encounter order: (db_idx, b.order)
                        existing=by_dist[d]
                        def enc(x): return (x[3],x[0].order)
                        if tie=="first" and enc(c)<enc(existing):
                            by_dist[d]=c
                        if tie=="last" and enc(c)>enc(existing):
                            by_dist[d]=c
                collapsed=list(by_dist.values())
                collapsed_sorted=sorted(collapsed, key=sort_key)
                selected=collapsed_sorted[:k_val]
            # if sortout, final output order should be by B start across DBs (within selected)
            if opts.get("-sortout"):
                selected=sorted(selected, key=lambda c:(c[0].chrom,c[0].start,c[0].end,c[3],c[0].order))
            for b,unsigned,ref_sign,db_idx in selected:
                line=a.to_line()
                if multi:
                    line+="\t"+db_label(db_idx,opts,b_paths)
                line+="\t"+format_b_record_line(b)
                if opts.get("-D"):
                    line+=f"\t{_signed_distance(a,b,unsigned,ref_sign,opts)}"
                elif opts.get("-d"):
                    line+=f"\t{unsigned}"
                out.append(line+"\n")
    sys.stdout.write("".join(out))
    return 0

def _signed_distance(a,b,unsigned,ref_sign,opts):
    if unsigned==0:
        return 0
    mode=opts.get("-D")
    if mode is None:
        return ref_sign*unsigned
    if mode=="ref":
        return ref_sign*unsigned
    if mode=="a":
        return ref_sign*unsigned*(-1 if a.strand=="-" else 1)
    if mode=="b":
        # B '+' => -ref, else ref
        return (-ref_sign*unsigned) if b.strand=="+" else (ref_sign*unsigned)
    return ref_sign*unsigned

def _closest_candidate(a,b,spec,opts):
    if a.chrom!=b.chrom:
        return None
    if not spec.strand_ok(a,b):
        return None
    if opts.get("-N"):
        # name comparison: for BED, col4; if both have names and equal, skip. What if name '.'? If both '.' (?) they are equal - would skip all BED3? Probe later.
        # bedtools uses getName() which for BED3 returns "." maybe? -N on BED3 would then file? We'll only apply if a.name==b.name (including '.')
        if a.name==b.name:
            return None
    unsigned,ref_sign,ov=_closest_distance(a,b,spec)
    if opts.get("-io") and ov>0:
        return None
    if ov>0:
        # fraction check must pass for overlapping
        ok,_ov=spec.check(a,b)
        if not ok:
            return None
    return (b,unsigned,ref_sign)
