class MT19937_64:
    NN=312; MM=156; MATRIX_A=0xB5026F5AA96619E9; UM=0xFFFFFFFF80000000; LM=0x7FFFFFFF
    def __init__(self, seed=0):
        seed=int(seed) & ((1<<64)-1)
        self.mt=[0]*self.NN
        self.mt[0]=seed
        for i in range(1,self.NN):
            prev=self.mt[i-1]
            self.mt[i]=(6364136223846793005*(prev ^ (prev>>62))+i) & ((1<<64)-1)
        self.mti=self.NN
    def gen(self):
        if self.mti>=self.NN:
            mag01=[0,self.MATRIX_A]
            mt=self.mt
            for i in range(self.NN-self.MM):
                x=(mt[i]&self.UM)|(mt[i+1]&self.LM)
                mt[i]=mt[i+self.MM] ^ (x>>1) ^ mag01[x&1]
            for i in range(self.NN-self.MM,self.NN-1):
                x=(mt[i]&self.UM)|(mt[i+1]&self.LM)
                mt[i]=mt[i+self.MM-self.NN] ^ (x>>1) ^ mag01[x&1]
            x=(mt[self.NN-1]&self.UM)|(mt[0]&self.LM)
            mt[self.NN-1]=mt[self.MM-1] ^ (x>>1) ^ mag01[x&1]
            self.mti=0
        y=self.mt[self.mti]; self.mti+=1
        y ^= (y>>29) & 0x5555555555555555
        y ^= (y<<17) & 0x71D67FFFEDA60000
        y ^= (y<<37) & 0xFFF7EEE000000000
        y ^= (y>>43)
        return y & ((1<<64)-1)
    # aliases
    def __call__(self):
        return self.gen()

def make_rng(seed_str):
    if seed_str is None:
        # bedtools default: seed chosen automatically - from time? Use system time in seconds/microces?
        # Original code likely uses time(0) or std::chrono. We'll use time.time_ns()
        import time
        seed=int(time.time())  # closest guess
        return MT19937_64(seed)
    try:
