import sys, os, math, time
from util import *
from records import *
from errhelp import *
from common import *
from sortedcheck import *
from ops import *
from rng import MT19937_64, make_rng

# ---------- merge ----------
def tool_merge(argv):
    tool="merge"
    parser=ArgParser(flags=["-s"]+NEW_COMMON_FLAGS, ones=["-i","-d","-S","-c","-o","-delim","-prec","-null"]+NEW_COMMON_ONES, multis=[])
    opts,unknown,missing=parser.parse(argv)
    # -S takes a strand arg, but could be "+" / "-": our parser ones consumes next token even if "-".
    # -d can be negative: parser consumes next token regardless
    if "-i" in missing:
        usage_new_error(tool, ["-i option given, but no input file specified."])
    prec=validate_prec(tool,opts)
    # validate -S arg if present
    if opts.get("-S") is not None and opts["-S"] not in ("+","-"):
        # What error in ref? Probe later - generic usage?
        usage_new_error(tool, ["-S must be followed by + or -."])  # may be refined
    if unknown:
        check_unknown(tool,unknown)
    if missing:
        # other missing (e.g -c) treat as unrecognized as observed? But if -d missing etc.
        others=[m for m in missing if m!="-i"]
        if others:
            usage_new_error(tool,[f"Unrecognized parameter: {m}" for m in others])
    in_path=opts.get("-i")  # may be None -> stdin
    records,info=read_records(in_path, style="new")
    # sorted check always for merge
    check_sorted_individual(records, in_path if in_path else "stdin")
    d_val=0
    if opts.get("-d") is not None:
        dv=parse_int(opts["-d"], None)
        if dv is None:
            d_val=0
        else:
            d_val=dv
    force_strand=bool(opts.get("-s"))
    specific_strand=opts.get("-S")
    # operations if -c specified or -o specified? If -c not specified but -o specified, default col 5? Merge help default 5 for -c.
    has_ops = opts.get("-c") is not None or opts.get("-o") is not None
    # Note if -s used, does output include strand as extra column in some versions? Observed merge -s output only chrom/start/end (no strand). Good.
    if has_ops:
        cols,ops_list,prec2,delim,nullval=parse_op_args(opts, default_col=5)
        prec=prec2 if opts.get("-prec") is not None else 10
        max_col=info.nfields if records else 0
        validate_ops_and_cols(cols,ops_list,max_col, in_path if in_path else "stdin")
        pairs=expanded_pairs(cols,ops_list)
    else:
        pairs=[]; delim=","; nullval="."
    if opts.get("-header"):
        if is_bam_file(info):
            sys.stderr.write("\n*****\n*****WARNING: -header option is not valid for BAM input.\n*****\n")
        else:
            for h in info.header: sys.stdout.write(h+"\n")
    # Split handling: if split, records expand to blocks as separate merging intervals but operations values from original record?
    # For BED12 split, merging should treat blocks as intervals. Our expansion below handles via creating subrecords for merging if split.
    work_records=[]
    if opts.get("-split"):
        for r in records:
            if r.blocks:
                for (s,e) in r.blocks:
                    sub=r.copy_with_coords(s,e)
                    # Preserve original fields for ops (sub.fields are original except coords); that's correct for ops
                    work_records.append(sub)
            else:
                work_records.append(r)
        # work records may be unsorted if blocks overlapping records could be out of order because original sorted but blocks of one record are increasing
    else:
        work_records=records
    # merge algorithm in input order
    out=[]
    cur=None  # dict with chrom,start,end,strand, recs list
    def flush(cur):
        if cur is None: return
        line=f"{cur['chrom']}\t{cur['start']}\t{cur['end']}"
        if has_ops:
            results=[]
            for col,op in pairs:
                vals=[get_col_value(rec.fields,col) for rec in cur['recs']]
                results.append(apply_op(vals,op,delim=delim,prec=prec,null=nullval,warn_col=col))
            if results:
                line+="\t"+"\t".join(results)
        out.append(line+"\n")
    for r in work_records:
        if specific_strand is not None and r.strand!=specific_strand:
            continue
        if cur is None:
            cur={'chrom':r.chrom,'start':r.start,'end':r.end,'strand':r.strand,'recs':[r]}
            continue
        # Decide merge: same chrom, (stranded if -s: same strand), distance check.
        # Distance: r.start - cur_end <= d  (if d positive allows gap, if d negative requires overlap at least -d: r.start - cur_end <= d (e.g d=-5, overlap >=5 => cur_end - r.start >=5 => r.start - cur_end <= -5)
        # For book-ended with d=0: r.start == cur_end => merge.
        same_chrom = (r.chrom==cur['chrom'])
        strand_ok=True
        if force_strand:
