def tool_sort(argv):
    tool="sort"
    parser=ArgParser(flags=["-sizeA","-sizeD","-chrThenSizeA","-chrThenSizeD","-chrThenScoreA","-chrThenScoreD","-header"], ones=["-i","-g","-faidx"])
    opts,unknown,missing=parser.parse(argv)
    if unknown:
        usage_old_error(tool, unknowns=unknown)
    in_path=opts.get("-i")
    records,info=read_records(in_path, style="old", allow_bam=False)
    # genome order if -g or -faidx
    genome=None; genome_path=opts.get("-g") or opts.get("-faidx")
    if genome_path:
        # sort genome error style: Cannot open ...
        try:
            genome=read_genome(genome_path, style="sort")
        except BedError as be:
            raise be
        # check each record chrom in genome, error if undefined: 'Chromosome "chr10" undefined in /tmp/... \n' (?) with blank?
        for r in records:
            if r.chrom not in genome:
                raise BedError(f'Chromosome "{r.chrom}" undefined in {genome_path}\n')
    if opts.get("-header"):
        for h in info.header: sys.stdout.write(h+"\n")
    def score_of(r):
        # score field depending format: BED col5 if exists else 0? SortBed uses getScore (?) which for BED3 is 0?
        if r.fmt=="bed" and len(r.fields)>=5:
            try: return float(r.fields[4])
            except: return 0
        if r.fmt=="gff":
            try: return float(r.fields[5])
            except: return 0
        return 0
    def size_of(r): return r.end-r.start
    # Sorting modes: bedtools sort default is chrom asc (lexicographic, or genome order if provided), then start asc, then end asc (?)
    # Need stable tie breakers probing. We'll implement keys and rely on stable sort for ties.
    if genome:
        order={c:i for i,c in enumerate(genome.keys())}
        chrom_key=lambda r: order[r.chrom]
    else:
        chrom_key=lambda r: r.chrom
    if opts.get("-sizeA"):
        key=lambda r: (size_of(r), chrom_key(r), r.start, r.end)
        records_sorted=sorted(records, key=key)
    elif opts.get("-sizeD"):
        key=lambda r: (-size_of(r), chrom_key(r), r.start, r.end)
        records_sorted=sorted(records, key=key)
    elif opts.get("-chrThenSizeA"):
        records_sorted=sorted(records, key=lambda r:(chrom_key(r), size_of(r), r.start, r.end))
    elif opts.get("-chrThenSizeD"):
        records_sorted=sorted(records, key=lambda r:(chrom_key(r), -size_of(r), r.start, r.end))
    elif opts.get("-chrThenScoreA"):
        records_sorted=sorted(records, key=lambda r:(chrom_key(r), score_of(r), r.start, r.end))
    elif opts.get("-chrThenScoreD"):
        records_sorted=sorted(records, key=lambda r:(chrom_key(r), -score_of(r), r.start, r.end))
    else:
        # default and genome/faidx
        records_sorted=sorted(records, key=lambda r:(chrom_key(r), r.start, r.end))
    out=[r.to_line()+"\n" for r in records_sorted]
    sys.stdout.write("".join(out))
    return 0

