    # Actually spacing requires input; if no -i and argv not empty? If opts -i is None, reference captured none gives No input... But spacing may read stdin if -i omitted? Earlier test spacing with stdin? Help varies.
    if opts.get("-i") is None and not argv:
        usage_new_error(tool,["No input file given. Exiting."])
    if unknown: check_unknown(tool,unknown)
    records,info=read_records(opts.get("-i"), style="new")
    if opts.get("-header"):
        if is_bam_file(info):
            sys.stderr.write("\n*****\n*****WARNING: -header option is not valid for BAM input.\n*****\n")
        else:
            for h in info.header: sys.stdout.write(h+"\n")
    out=[]
    prev=None
    for r in records:
        if prev is None or r.chrom!=prev.chrom:
            spacing="."
        else:
            dist=r.start-prev.end
            if dist<0:
                spacing="-1"
            else:
                spacing=str(dist)
        out.append(f"{r.to_line()}\t{spacing}\n")
        prev=r
    sys.stdout.write("".join(out))
    return 0

