# ---------- genomecov ----------
def tool_genomecov(argv):
    tool="genomecov"
    parser=ArgParser(flags=["-d","-dz","-bg","-bga","-split","-ignoreD","-pc","-du","-5","-3","-trackline"], ones=["-i","-ibam","-g","-strand","-fs","-max","-scale","-trackopts"])
    opts,unknown,missing=parser.parse(argv)
    # old tool validation: many conditions - probe via differential later. Approximate:
    validations=[]
    if opts.get("-i") is None and opts.get("-ibam") is None:
        # genomecov with no args captured none equals -h output (just usage) - because old tools if argc==1 print usage only. Dispatcher does not special case empty; our function when argv empty will go here.
        # If argv empty, simply emit h variant
        if not argv:
            raise BedError(h_text(tool),1)
        validations.append(old_validation_block("Need -i or -ibam file. ")) # placeholder might not match - will refine
    if opts.get("-ibam") is None and opts.get("-g") is None:
        if argv:
            validations.append(old_validation_block("Need -g genome file. "))
    if opts.get("-bg") and opts.get("-bga"):
        pass # ?
    if unknown or validations:
        # genomecov old with unknown: prefixes + validations? In bad example, after unknown there was also *** Need ...?
        # Use old usage error only if unknown; if validation only, use those blocks.
        if unknown:
            usage_old_error(tool, unknowns=unknown, validation=validations)
        elif validations:
            usage_old_error(tool, unknowns=[], validation=validations)
    # Load genome / records
    is_bam_input=False; records=[]; info=None; genome=None
    if opts.get("-ibam"):
        # -ibam file must be BAM; if missing file, htslib error style: from bamtobed probe genomecov ibam nonexistent later.
        path=opts["-ibam"]
        if not os.path.exists(path) and path not in ("stdin","-"):
            raise BedError(f"[E::hts_open_format_impl] Failed to open file {path}\nFailed to open BAM file {path}\n")
        records,info=read_records(path, style="old", allow_bam=True)
        is_bam_input=True
        # genome from BAM refs in order
        from collections import OrderedDict as OD
        genome=OD()
        for name,length in info.refs:
            genome[name]=length
        if opts.get("-g"):
            # if -g also given with ibam, maybe override? Probably ignore / use genome file order? Probe later.
            genome=read_genome(opts["-g"], style="new")
    else:
        genome=read_genome(opts["-g"], style="new")  # genomecov genome error style is Can't open...
        records,info=read_records(opts.get("-i"), style="old", allow_bam=False)
        # note genomecov -i could also be BAM? No -ibam needed.
    # Input BED must be grouped by chrom - does it validate? If a chrom returns after another, their coverage algorithm (streaming per chrom) may output per chrom in encounter order and miss - our per genome order approach might differ in grouped violations. Tests likely grouped.
    strand_filter=opts.get("-strand")
    scale=parse_float(opts.get("-scale"),1.0) if opts.get("-scale") else 1.0
    max_depth=None
    if opts.get("-max") is not None:
        max_depth=parse_int(opts["-max"],None)
    # Compute coverage per chrom as events (diff array using dict of breakpoints) to support large genome sizes without allocating per-base arrays for histogram/bg.
    # For -d/-dz output needs per position, we'll expand segments (output size itself is per base).
    # Build intervals per chrom
    from collections import defaultdict as DD
    intervals_by_chrom=DD(list)
    for r in records:
        if strand_filter in ("+","-") and r.strand!=strand_filter:
            continue
        if is_bam_input and r.bam is not None:
            # special BAM options: -pc (paired fragments), -fs, -du, -5/-3, -ignoreD etc -> complex; implement basic for now, will enhance in bam section.
            if r.bam.is_unmapped():
                continue
            if opts.get("-5"):
                # 5' position: for + strand start, - strand end-1
                if r.strand=="-":
                    intervals_by_chrom[r.chrom].append((r.end-1,r.end))
                else:
                    intervals_by_chrom[r.chrom].append((r.start,r.start+1))
                continue
            if opts.get("-3"):
                if r.strand=="-":
                    intervals_by_chrom[r.chrom].append((r.start,r.start+1))
                else:
                    intervals_by_chrom[r.chrom].append((r.end-1,r.end))
                continue
            if opts.get("-split"):
                # BAM split uses N and D unless -ignoreD then only N?
                blocks=r.bam.blocks if opts.get("-ignoreD") else r.bam.blocks_ND
                for s,e in blocks:
                    intervals_by_chrom[r.chrom].append((s,e))
                continue
            else:
                # Without split, BAM coverage in genomecov: they still consider deletions? Earlier b12 BAM -bg without split gave 100-500 contiguous (N included). With D in CIGAR, without split or ignoreD, what? Their default for BAM is to count D as covered? -ignoreD says ignore local deletions when computing coverage, implying normally deletions are counted as coverage (i.e span). Good span.
                intervals_by_chrom[r.chrom].append((r.start,r.end))
                continue
        # non-BAM
        if opts.get("-5"):
            if r.strand=="-":
                intervals_by_chrom[r.chrom].append((r.end-1,r.end))
            else:
                intervals_by_chrom[r.chrom].append((r.start,r.start+1))
            continue
        if opts.get("-3"):
            if r.strand=="-":
                intervals_by_chrom[r.chrom].append((r.start,r.start+1))
            else:
                intervals_by_chrom[r.chrom].append((r.end-1,r.end))
            continue
        if opts.get("-split") and r.blocks:
            for s,e in r.blocks:
                intervals_by_chrom[r.chrom].append((s,e))
        else:
            intervals_by_chrom[r.chrom].append((r.start,r.end))
    # Function to get segments (start,end,depth_raw) per chrom (depth before max/scale)
    def chrom_segments(chrom):
        size=genome.get(chrom,0)
        events={}
        for s,e in intervals_by_chrom.get(chrom,[]):
            s=max(s,0); e=min(e,size)
            if e<=s: continue
            events[s]=events.get(s,0)+1
            events[e]=events.get(e,0)-1
        points=sorted(set([0,size]+[p for p in events.keys() if 0<=p<=size]))
        segs=[]; depth=0
        for i in range(len(points)-1):
            p=points[i]; np=points[i+1]
            depth+=events.get(p,0)
            if np>p:
                segs.append((p,np,depth))
        return segs
    def fmt_depth(d_raw):
        d=d_raw
        if max_depth is not None and (opts.get("-bg") or opts.get("-bga") or opts.get("-d") or opts.get("-dz")):
            # help says -max irrelevant for -d and bedGraph, but earlier test -max 1 -bg DID cap depth to 1 ( contradict help / our earlier small test showed bg capped). So apply max for bg as well based on observation.
            if d>max_depth: d=max_depth
        if scale!=1.0:
            v=d*scale
            return fmt_g(v,10) if False else (("%g"%v))  # genomecov scale formatting ? use %g default 6?
            # observed 2.5 and 5 -> %g works
        else:
            return str(d)
    # Trackline
