def _merged_segments(records, split=False):
    from collections import defaultdict
    per=defaultdict(list)
    for r in records:
        for s,e in r.effective_intervals(split):
            per[r.chrom].append((s,e))
    merged={}
    total=0
    for chrom,segs in per.items():
        segs.sort()
        m=[]
        for s,e in segs:
            if e<=s: continue
            if m and s<=m[-1][1]:
                m[-1]=(m[-1][0],max(m[-1][1],e))
            else:
                m.append((s,e))
        merged[chrom]=m
        total+=sum(e-s for s,e in m)
    return merged,total

