def _hypergeom_pmf(k,N,Ksuc,n_draw):
    # P(X=k)
    if k<max(0,n_draw-(N-Ksuc)) or k>min(Ksuc,n_draw):
        return 0.0
    # use math.comb with logs for large
    try:
        return math.comb(Ksuc,k)*math.comb(N-Ksuc,n_draw-k)/math.comb(N,n_draw)
    except Exception:
        # log method
        def lcomb(nn,kk):
            return math.lgamma(nn+1)-math.lgamma(kk+1)-math.lgamma(nn-kk+1)
        return math.exp(lcomb(Ksuc,k)+lcomb(N-Ksuc,n_draw-k)-lcomb(N,n_draw))

