# ---------- Fasta helpers ----------
class FastaRec:
    def __init__(self,header,seq_lines):
        self.header=header  # without >
        self.seq_lines=seq_lines
        self.seq="".join(seq_lines)
    @property
    def name(self):
        # first word (space or tab)
        return re.split(r'[ \t]',self.header,1)[0] if self.header else ""

def _read_fasta(path, style="fasta_db"):
    if path is None or (path not in ("stdin","-") and not os.path.exists(path) and not str(path).startswith("/dev/fd/")):
        if style=="fasta_db":
            raise BedError(f"Error: The requested fasta database file ({path}) could not be opened. Exiting!\n")
        elif style=="fasta":
            raise BedError(f"Error: The requested fasta file ({path}) could not be opened. Exiting!\n")
        else:
            raise BedError(f"Error: The requested fasta database file ({path}) could not be opened. Exiting!\n")
    lines=read_text_lines(path)
    recs=[]; header=None; seq_lines=[]
    # For .fai creation we need offsets based on raw bytes - compute later in _maybe_create_fai separately by reading raw.
    for line in lines:
        if line.startswith(">"):
            if header is not None:
                recs.append(FastaRec(header,seq_lines))
            header=line[1:]; seq_lines=[]
        else:
            if header is None:
                # sequence before header - ignore / create empty?
                continue
            seq_lines.append(line)
    if header is not None:
        recs.append(FastaRec(header,seq_lines))
    return recs

def _fasta_dict(recs, full_header=False):
    d={}
    order=[]
    for r in recs:
        key=r.header if full_header else r.name
        if key not in d:
            order.append(key)
        d[key]=r
    return d,order

def _maybe_create_fai(path):
    if path is None or path in ("stdin","-") or str(path).startswith("/dev/fd/") or path=="/dev/stdin":
        return
    fai_path=str(path)+".fai"
