        return
    try:
        raw=read_binary_raw(path)
        if raw[:2]==b"\x1f\x8b":
            # gzipped fasta - faidx creates .gzi too etc. Skip for now.
            return
        # Parse raw lines keeping offsets
        lines=raw.split(b"\n")
        # If file ends with newline, last split empty not a line.
        offset=0; entries=[]; cur=None
        # We need iterate with actual line byte lengths including newline except possibly last.
        pos=0; idx=0
        raw_lines=[]
        while pos < len(raw):
            nl=raw.find(b"\n",pos)
            if nl==-1:
                raw_lines.append((raw[pos:],pos,len(raw)-pos))
                break
