            if opts.get("-C"):
                hay=seq.upper(); needle=pattern.upper()
            else:
                hay=seq; needle=pattern
            cnt=0; pos=0
            if needle:
                while True:
                    idx=hay.find(needle,pos)
                    if idx==-1: break
