    if opts.get("-fi") is None or opts.get("-bed") is None or opts.get("-fo") is None:
        raise BedError(h_text(tool),1)
    fasta_recs=_read_fasta(opts["-fi"], style="fasta")
    records,info=read_records(opts["-bed"], style="old", allow_bam=False)
    # build mask intervals per chrom name (key by first word or full header)
    from collections import defaultdict
    masks=defaultdict(list)
    for r in records:
        masks[r.chrom].append((r.start,r.end))
    mc=opts.get("-mc")
    mask_char=mc[0] if mc else "N"
    out_lines=[]
    for frec in fasta_recs:
        key=frec.header if opts.get("-fullHeader") else frec.name
        seq_chars=list(frec.seq)
        for s,e in masks.get(key,[]):
            s=max(s,0); e=min(e,len(seq_chars))
            for i in range(s,e):
                if opts.get("-soft"):
                    seq_chars[i]=seq_chars[i].lower()
                else:
                    seq_chars[i]=mask_char
        out_lines.append(f">{frec.header}\n")
        # preserve line wrapping from original seq_lines lengths
        pos=0
        if frec.seq_lines:
            for original_line in frec.seq_lines:
                ln=len(original_line)
                chunk="".join(seq_chars[pos:pos+ln]); pos+=ln
                out_lines.append(chunk+"\n")
            if pos < len(seq_chars):
                out_lines.append("".join(seq_chars[pos:])+"\n")
        else:
            if seq_chars:
                out_lines.append("".join(seq_chars)+"\n")
    with open(opts["-fo"],"w") as out:
        out.write("".join(out_lines))
    return 0

