# ---------- Fasta helpers ----------
class FastaRec:
    def __init__(self,header,seq_lines):
        self.header=header  # without >
        self.seq_lines=seq_lines
        self.seq="".join(seq_lines)
    @property
    def name(self):
        # first word (space or tab)
        return re.split(r'[ \t]',self.header,1)[0] if self.header else ""

def _read_fasta(path, style="fasta_db"):
    if path is None or (path not in ("stdin","-") and not os.path.exists(path) and not str(path).startswith("/dev/fd/")):
        if style=="fasta_db":
            raise BedError(f"Error: The requested fasta database file ({path}) could not be opened. Exiting!\n")
        elif style=="fasta":
            raise BedError(f"Error: The requested fasta file ({path}) could not be opened. Exiting!\n")
        else:
            raise BedError(f"Error: The requested fasta database file ({path}) could not be opened. Exiting!\n")
    lines=read_text_lines(path)
    recs=[]; header=None; seq_lines=[]
    # For .fai creation we need offsets based on raw bytes - compute later in _maybe_create_fai separately by reading raw.
    for line in lines:
        if line.startswith(">"):
            if header is not None:
                recs.append(FastaRec(header,seq_lines))
            header=line[1:]; seq_lines=[]
        else:
            if header is None:
                # sequence before header - ignore / create empty?
                continue
            seq_lines.append(line)
    if header is not None:
        recs.append(FastaRec(header,seq_lines))
    return recs

def _fasta_dict(recs, full_header=False):
    d={}
    order=[]
    for r in recs:
        key=r.header if full_header else r.name
        if key not in d:
            order.append(key)
        d[key]=r
    return d,order

def _maybe_create_fai(path):
    if path is None or path in ("stdin","-") or str(path).startswith("/dev/fd/") or path=="/dev/stdin":
        return
    fai_path=str(path)+".fai"
    if os.path.exists(fai_path):
        return
    try:
        raw=read_binary_raw(path)
        if raw[:2]==b"\x1f\x8b":
            # gzipped fasta - faidx creates .gzi too etc. Skip for now.
            return
        # Parse raw lines keeping offsets
        lines=raw.split(b"\n")
        # If file ends with newline, last split empty not a line.
        offset=0; entries=[]; cur=None
        # We need iterate with actual line byte lengths including newline except possibly last.
        pos=0; idx=0
        raw_lines=[]
        while pos < len(raw):
            nl=raw.find(b"\n",pos)
            if nl==-1:
                raw_lines.append((raw[pos:],pos,len(raw)-pos))
                break
            else:
                raw_lines.append((raw[pos:nl],pos,nl-pos+1))
                pos=nl+1
        for line_bytes,line_offset,total_len in raw_lines:
            # strip trailing \r for parsing
            line=line_bytes[:-1] if line_bytes.endswith(b"\r") else line_bytes
            if line.startswith(b">"):
                if cur is not None:
                    entries.append(cur)
                header=line[1:].decode('utf-8',errors='surrogateescape')
                name=re.split(r'[ \t]',header,1)[0]
                cur={"name":name,"length":0,"offset":line_offset+total_len,"linebases":None,"linewidth":None}
            else:
                if cur is None: continue
                bases=len(line)
                if cur["linebases"] is None:
                    cur["linebases"]=bases
                    cur["linewidth"]=total_len if line_bytes!=b"" or total_len else bases
                    # linewidth in bytes including newline; if last line has no newline, samtools still uses first line's width as bases+1?
                    # total_len already includes \n if present, or just bases (+\r) if final line w/o newline -> for fai, linewidth should be linebases+ newline length (maybe)
                    if total_len==bases or total_len==bases+1 and line_bytes.endswith(b"\r"):
                        # no LF
                        cur["linewidth"]=bases+(2 if line_bytes.endswith(b"\r") else 1)
                cur["length"]+=bases
        if cur is not None:
            entries.append(cur)
        with open(fai_path,"w") as out:
            for e in entries:
                lb=e["linebases"] if e["linebases"] is not None else 0
                lw=e["linewidth"] if e["linewidth"] is not None else lb
                out.write(f"{e['name']}\t{e['length']}\t{e['offset']}\t{lb}\t{lw}\n")
    except Exception:
