def _revcomp(seq, rna=False):
    if rna:
        table=str.maketrans("ACGTRYMKWSBDHVNacgtrymkwsbdhvnUu","UGCAAYRKWSHVDBNugc aayrkwshvdbnAa".replace(" ",""))
        # The above mapping string must be aligned; safer build dict manually below
        comp={'A':'U','C':'G','G':'C','T':'A','U':'A','R':'Y','Y':'R','M':'K','K':'M','W':'W','S':'S','B':'V','D':'H','H':'D','V':'B','N':'N','a':'u','c':'g','g':'c','t':'a','u':'a','r':'y','y':'r','m':'k','k':'m','w':'w','s':'s','b':'v','d':'h','h':'d','v':'b','n':'n'}
        return "".join(comp.get(ch,ch) for ch in reversed(seq))
    else:
        comp={'A':'T','C':'G','G':'C','T':'A','U':'A','R':'Y','Y':'R','M':'K','K':'M','W':'W','S':'S','B':'V','D':'H','H':'D','V':'B','N':'N','a':'t','c':'g','g':'c','t':'a','u':'a','r':'y','y':'r','m':'k','k':'m','w':'w','s':'s','b':'v','d':'h','h':'d','v':'b','n':'n'}
        return "".join(comp.get(ch,ch) for ch in reversed(seq))

def _extract_seq_for_record(r, fasta_dict, full_header=False, split=False, strand_aware=False, rna=False):
    # returns (seq or None, warning_msg or None)
    key=r.chrom
    frec=fasta_dict.get(key)
    if frec is None:
        return None, f"WARNING. chromosome ({r.chrom}) was not found in the FASTA file. Skipping.\n"
    seq_full=frec.seq
    if r.end > len(seq_full):
        return None, f"Feature ({r.chrom}:{r.start}-{r.end}) beyond the length of {r.chrom} size ({len(seq_full)} bp).  Skipping.\n"
    if split and r.blocks:
        seq="".join(seq_full[s:e] for s,e in r.blocks)
    else:
        seq=seq_full[r.start:r.end]
    if strand_aware and r.strand=="-":
        seq=_revcomp(seq,rna=rna)
    return seq,None

