    sys.stdout.write(preamble)
    sys.stdout.flush()
    records,info=read_records(in_path, style="old", allow_bam=False)
    out=[]
    for r in records:
        # UCSC position uses start - ? in href position=chrom:start-end where start is BED start (0-based) as given? observed position=chr1:100-200 for BED 100-200, display text chr1:101-200 (1-based start)
        href=f"{base}/cgi-bin/hgTracks?org={org}&db={dbv}&position={r.chrom}:{r.start}-{r.end}"
        display=f"{r.chrom}:{r.start+1}-{r.end}"
        out.append("<tr>\n\t<td>\n")
        out.append(f"\t\t<a href={href}>{display}</a>\n")
        out.append("\t</td>\n")
        # Remaining fields (from 4th onward) each as a table cell with its own lines? Observed for BED6, fields name,score,strand each in <td>\nfield\n\t</td>
        for field in r.fields[3:]:
