def tool_igv(argv):
    tool="igv"
    parser=ArgParser(flags=["-clps","-name"], ones=["-i","-path","-sess","-sort","-slop","-img"])
    opts,unknown,missing=parser.parse(argv)
    if unknown:
        usage_old_error(tool, unknowns=unknown)
    in_path=opts.get("-i")
    # igv with no input reads stdin and outputs just snapshotDirectory line (observed empty stdin gave 21 bytes "snapshotDirectory ./\n"? check)
    # Load records old with bed file error style if file missing - but before that does it output snapshotDirectory? In nonexist test, stdout was '' (?), so file open happens before printing. We'll load first.
    records,info=None,None
    if in_path is not None and in_path not in ("stdin","-") and not os.path.exists(in_path):
        raise BedError(f"Error: The requested bed file ({in_path}) could not be opened. Exiting!\n")
    records,info=read_records(in_path, style="old", allow_bam=False)
    path=opts.get("-path") or "./"
    out=[f"snapshotDirectory {path}\n"]
    if opts.get("-sess"):
        out.append(f"load {opts['-sess']}\n")
    # sort/clps commands: need investigate exact lines. Probe later; basic handling based on IGV batch commands known:
    # For each record, goto and optional sort/collapse, then snapshot
    slop_val=parse_int(opts.get("-slop"),0) if opts.get("-slop") else 0
    img=opts.get("-img") or "png"
    for r in records:
        start=r.start-slop_val; end=r.end+slop_val
        out.append(f"goto {r.chrom}:{start}-{end}\n")
        if opts.get("-sort"):
            out.append(f"sort {opts['-sort']}\n")
        if opts.get("-clps"):
            out.append("collapse\n")
        if opts.get("-name"):
