        else:
            fname=f"{r.chrom}_{start}_{end}.{img}" if slop_val else f"{r.chrom}_{r.start}_{r.end}.{img}"
            # Wait if slop, filename presumably uses slopped coords or original? Probe later
        out.append(f"snapshot {fname}\n")
    sys.stdout.write("".join(out))
