def _multi_segments(file_records_list, genome=None, empty=False):
    # file_records_list: list of records per file (already sorted as input)
    # Build per chrom segments: all breakpoints from intervals (and genome boundaries if empty)
    # Then merge adjacent elementary segments with same file set (for multiinter).
    from collections import defaultdict
    chroms_order=[]
    # Order chromosomes by order of appearance in first file? But original uses sorted sweep order: chromosomes processed in order encountered by earliest record among files lexicographically? Inputs sorted lexicographically normally.
    # Determine chrom list: genome order if genome provided and empty, else sort order as first seen in any file (preserving input file order scanning records in order).
    seen=set()
    all_recs_by_file=file_records_list
    # To mimic sweep: collect chroms from records sorted by (?) We'll get order from merging all records sorted by chrom order as they appear when scanning files in order and records in order.
    for recs in all_recs_by_file:
        for r in recs:
            if r.chrom not in seen:
                seen.add(r.chrom); chroms_order.append(r.chrom)
    if genome is not None:
        # Use genome order for chroms that are in genome, plus records chroms not in genome at end?
        genome_chroms=[c for c in genome.keys() if empty or c in seen]
        # If empty, all genome chroms; else maybe only seen but in genome order
        chroms_order=genome_chroms + [c for c in chroms_order if c not in genome]
    segments_by_chrom={}
    for chrom in chroms_order:
        points=set()
        per_file_intervals=[]
        for recs in all_recs_by_file:
            ivs=[(r.start,r.end) for r in recs if r.chrom==chrom]
            per_file_intervals.append(ivs)
            for s,e in ivs:
                points.add(s); points.add(e)
        if empty and genome is not None and chrom in genome:
            points.add(0); points.add(genome[chrom])
        pts=sorted(points)
        segs=[]
        for i in range(len(pts)-1):
            s=pts[i]; e=pts[i+1]
            if e<=s: continue
            cover=[]
            for fi,ivs in enumerate(per_file_intervals):
                # determine if any interval covers [s,e) - since points are breakpoints, check s inside
                cov=any(sv<=s<ev or (s==e and False) for sv,ev in ivs)
                # More robust overlap of segment with interval >0
                cov=any(min(e,ev)>max(s,sv) for sv,ev in ivs)
                cover.append(cov)
            segs.append([s,e,tuple(cover)])
        # Merge adjacent segs with same cover set
        merged=[]
        for s,e,cov in segs:
            if merged and merged[-1][1]==s and merged[-1][2]==cov:
                merged[-1][1]=e
            else:
                merged.append([s,e,cov])
        segments_by_chrom[chrom]=merged
    return chroms_order,segments_by_chrom

