# ---------- multiinter / unionbedg shared ----------
def _multi_segments(file_records_list, genome=None, empty=False):
    # file_records_list: list of records per file (already sorted as input)
    # Build per chrom segments: all breakpoints from intervals (and genome boundaries if empty)
    # Then merge adjacent elementary segments with same file set (for multiinter).
    from collections import defaultdict
    chroms_order=[]
    # Order chromosomes by order of appearance in first file? But original uses sorted sweep order: chromosomes processed in order encountered by earliest record among files lexicographically? Inputs sorted lexicographically normally.
    # Determine chrom list: genome order if genome provided and empty, else sort order as first seen in any file (preserving input file order scanning records in order).
    seen=set()
    all_recs_by_file=file_records_list
    # To mimic sweep: collect chroms from records sorted by (?) We'll get order from merging all records sorted by chrom order as they appear when scanning files in order and records in order.
    for recs in all_recs_by_file:
        for r in recs:
            if r.chrom not in seen:
                seen.add(r.chrom); chroms_order.append(r.chrom)
    if genome is not None:
        # Use genome order for chroms that are in genome, plus records chroms not in genome at end?
        genome_chroms=[c for c in genome.keys() if empty or c in seen]
        # If empty, all genome chroms; else maybe only seen but in genome order
        chroms_order=genome_chroms + [c for c in chroms_order if c not in genome]
    segments_by_chrom={}
    for chrom in chroms_order:
        points=set()
        per_file_intervals=[]
        for recs in all_recs_by_file:
            ivs=[(r.start,r.end) for r in recs if r.chrom==chrom]
            per_file_intervals.append(ivs)
            for s,e in ivs:
                points.add(s); points.add(e)
        if empty and genome is not None and chrom in genome:
            points.add(0); points.add(genome[chrom])
        pts=sorted(points)
        segs=[]
        for i in range(len(pts)-1):
            s=pts[i]; e=pts[i+1]
            if e<=s: continue
            cover=[]
            for fi,ivs in enumerate(per_file_intervals):
                # determine if any interval covers [s,e) - since points are breakpoints, check s inside
                cov=any(sv<=s<ev or (s==e and False) for sv,ev in ivs)
                # More robust overlap of segment with interval >0
                cov=any(min(e,ev)>max(s,sv) for sv,ev in ivs)
                cover.append(cov)
            segs.append([s,e,tuple(cover)])
        # Merge adjacent segs with same cover set
        merged=[]
        for s,e,cov in segs:
            if merged and merged[-1][1]==s and merged[-1][2]==cov:
                merged[-1][1]=e
            else:
                merged.append([s,e,cov])
        segments_by_chrom[chrom]=merged
    return chroms_order,segments_by_chrom

def tool_multiinter(argv):
    tool="multiinter"
    # Special parser: unknown tokens ignored, -i multi, -names multi, -g one, -filler one, flags cluster/header/empty/examples
    if "-examples" in argv:
        from examples_data import EXAMPLES
        e=EXAMPLES["multiinter"]
        if e['out']: sys.stdout.write(e['out'])
        if e['err']: sys.stderr.write(e['err'])
        return e['rc']
    if not argv:
        return emit_variant(tool,"none")
    parser=ArgParser(flags=["-cluster","-header","-empty"], ones=["-g","-filler"], multis=["-i","-names"])
    opts,unknown,missing=parser.parse(argv)
    # multiinter ignores unknown (observed)
    files=opts.get("-i") or []
    if not files:
        raise BedError("Error: missing file names (-i) to combine.\n")
    # If only one file? Probe later - probably works?
    genome=None
    if opts.get("-empty"):
        if not opts.get("-g"):
            # error message? probe later
            raise BedError("Error: -empty option requires a genome file (-g).\n")
    if opts.get("-g"):
        genome=read_genome(opts["-g"], style="old")  # genome error for multiinter? It uses genome file reader - style unknown; old BedFile genome maybe "Can't open"? We'll use new genome style (?) check in differentials
    file_recs=[]
    for f in files:
        recs,info=read_records(f, style="old", allow_bam=False)
        file_recs.append(recs)
    names=opts.get("-names") or []
    header_names=[]
    if names:
        header_names=names
    else:
        header_names=files
    out=[]
    if opts.get("-header"):
        out.append("chrom\tstart\tend\tnum\tlist\t"+"\t".join(header_names)+"\n" if header_names else "chrom\tstart\tend\tnum\tlist\n")
    chroms,segments_by_chrom=_multi_segments(file_recs, genome=genome, empty=bool(opts.get("-empty")))
    for chrom in chroms:
        segs=segments_by_chrom.get(chrom,[])
        # For cluster mode, filter to local maximal segments
        emit_flags=[True]*len(segs)
        if opts.get("-cluster"):
            emit_flags=[]
            for idx,(s,e,cov) in enumerate(segs):
                cov_set={i for i,c in enumerate(cov) if c}
                suppressed=False
                # check physically adjacent neighbors
                if idx>0:
                    ps,pe,pcov=segs[idx-1]
                    if pe==s:
                        pset={i for i,c in enumerate(pcov) if c}
                        if cov_set and cov_set < pset:
                            suppressed=True
                        if not cov_set and pset:
                            suppressed=True
                if idx < len(segs)-1:
                    ns,ne,ncov=segs[idx+1]
                    if ns==e:
                        nset={i for i,c in enumerate(ncov) if c}
                        if cov_set and cov_set < nset:
                            suppressed=True
                        if not cov_set and nset:
                            suppressed=True
                emit_flags.append(not suppressed)
        for (s,e,cov),emit in zip(segs,emit_flags):
            if not emit: continue
            num=sum(1 for c in cov if c)
            if num==0 and not opts.get("-empty"):
                continue
            if num==0:
                lst="none"
            else:
                if names:
                    lst=",".join(names[i] if i<len(names) else str(i+1) for i,c in enumerate(cov) if c)
                else:
                    lst=",".join(str(i+1) for i,c in enumerate(cov) if c)
            indicators="\t".join("1" if c else "0" for c in cov)
            out.append(f"{chrom}\t{s}\t{e}\t{num}\t{lst}\t{indicators}\n")
    sys.stdout.write("".join(out))
    return 0

def tool_unionbedg(argv):
    tool="unionbedg"
    if "-examples" in argv:
        from examples_data import EXAMPLES
        e=EXAMPLES["unionbedg"]
        if e['out']: sys.stdout.write(e['out'])
        if e['err']: sys.stderr.write(e['err'])
        return e['rc']
    if not argv:
        return emit_variant(tool,"none")
    parser=ArgParser(flags=["-header","-empty"], ones=["-g","-filler"], multis=["-i","-names"])
    opts,unknown,missing=parser.parse(argv)
    files=opts.get("-i") or []
    if not files:
        raise BedError("Error: missing BedGraph file names (-i) to combine.\n")
    if len(files)==1:
        raise BedError("Error: Only a single BedGraph file was specified. Nothing to combine, exiting.\n")
    genome=None
    if opts.get("-g"):
        genome=read_genome(opts["-g"], style="old")
    # BedGraph records: value is field4 (if Bed format thing) - our record parser will parse as BED4 name=value string. Good.
    file_recs=[]
    for f in files:
        recs,info=read_records(f, style="old", allow_bam=False)
        file_recs.append(recs)
    names=opts.get("-names") or []
    header_names=names if names else files
    out=[]
    if opts.get("-header"):
        out.append("chrom\tstart\tend\t"+"\t".join(header_names)+"\n")
    filler=opts.get("-filler") if opts.get("-filler") is not None else "0"
    empty=bool(opts.get("-empty"))
    # Build per chrom segments WITHOUT merging same values (break at all points), but merge? observed preserved boundaries.
    # Order chroms as in _multi_segments but need raw segments, not merged by set. We'll reuse points logic separately.
    # Determine chrom order
    chroms_order=[]; seen=set()
    for recs in file_recs:
        for r in recs:
            if r.chrom not in seen:
                seen.add(r.chrom); chroms_order.append(r.chrom)
    if genome is not None and empty:
        chroms_order=[c for c in genome.keys()] + [c for c in chroms_order if c not in genome]
    for chrom in chroms_order:
        points=set()
        per_file=[]
        for recs in file_recs:
            ivs=[]
            for r in recs:
                if r.chrom==chrom:
                    val=r.fields[3] if len(r.fields)>=4 else "0"
                    ivs.append((r.start,r.end,val))
                    points.add(r.start); points.add(r.end)
            per_file.append(ivs)
        if empty and genome is not None and chrom in genome:
            points.add(0); points.add(genome[chrom])
        pts=sorted(points)
        for i in range(len(pts)-1):
            s=pts[i]; e=pts[i+1]
            if e<=s: continue
            vals=[]
            any_cov=False
            for ivs in per_file:
                v=filler
                for sv,ev,val in ivs:
                    if min(e,ev)>max(s,sv):
                        v=val; any_cov=True; break
                vals.append(v)
            if not any_cov and not empty:
                continue
            out.append(f"{chrom}\t{s}\t{e}\t"+"\t".join(vals)+"\n")
    sys.stdout.write("".join(out))
    return 0

