def _bedpe_from_bam_records(records):
    # Convert adjacent paired BAM records into BEDPE-like objects with first encountered order
    from records import BEDPERecord
    pairs=[]
    alns=[r for r in records if r.bam is not None and not r.bam.is_unmapped()]
    i=0
    while i < len(alns):
        r1=alns[i]; a1=r1.bam
        if i+1 < len(alns) and alns[i+1].bam.read_name==a1.read_name:
            r2=alns[i+1]; a2=r2.bam
            # score min mapq
            score=str(min(a1.mapq,a2.mapq))
            fields=[a1.chrom,str(a1.start),str(a1.end),a2.chrom,str(a2.start),str(a2.end),a1.read_name,score,a1.strand,a2.strand]
            pe=BEDPERecord(fields, order=len(pairs))
            pe._bam_pair=(r1,r2)
            pairs.append(pe)
            i+=2
        else:
            if i==len(alns)-1:
                # duplicate singleton like bamtobed bedpe behavior?
                fields=[a1.chrom,str(a1.start),str(a1.end),a1.chrom,str(a1.start),str(a1.end),a1.read_name,str(a1.mapq),a1.strand,a1.strand]
                pe=BEDPERecord(fields, order=len(pairs)); pe._bam_pair=(r1,r1); pairs.append(pe)
            i+=1
    return pairs

