            continue
        hits1=hits_for(pe.chrom1,pe.start1,pe.end1,pe.strand1)
        hits2=hits_for(pe.chrom2,pe.start2,pe.end2,pe.strand2)
        has1=bool(hits1); has2=bool(hits2)
        report_hits=[]
        report_a_only=False
        if type_val=="either":
            report_hits=[(hits1),(hits2)]
        elif type_val=="both":
            if has1 and has2: report_hits=[hits1,hits2]
        elif type_val=="xor":
            if has1 ^ has2: report_hits=[hits1,hits2]
        elif type_val=="neither":
            if not has1 and not has2: report_a_only=True
        elif type_val=="notboth":
            if not (has1 and has2):
                if has1 or has2: report_hits=[hits1,hits2]
                else: report_a_only=True
