            if report_a_only or any(report_hits):
                # Avoid duplicating singleton duplicate pair?
                pair=pe._bam_pair
                # preserve unique records in pair but if singleton duplicate (same object twice) write once
                seen=set()
                for rec in pair:
                    if id(rec) not in seen:
                        keep_bam.append(rec); seen.add(id(rec))
        else:
            if report_a_only:
                out.append(pe.to_line()+"\n")
