        write_bam_filtered(bam_info, keep_bam, opts)
        return 0
    sys.stdout.write("".join(out))
    return 0

# ---------- pairtopair ----------
def tool_pairtopair(argv):
    tool="pairtopair"
    parser=ArgParser(flags=["-ss","-is","-rdn"], ones=["-a","-b","-f","-type","-slop"])
    opts,unknown,missing=parser.parse(argv)
    type_val=opts.get("-type") or "both"
    validations=[]
    if type_val not in ("both","either","neither","notboth"):
        raise BedError("\n*****\n*****ERROR: Request \"both\",\"neither\",\"either\",or \"notboth\"\n*****\n\n"+h_text(tool),1)
    if opts.get("-a") is None or opts.get("-b") is None:
        validations.append(old_validation_block("Need -a and -b files. "))
    if unknown or validations:
        usage_old_error(tool, unknowns=unknown, validation=validations)
    from records import read_bedpe
    a_recs,a_info=read_bedpe(opts["-a"])
    b_recs,b_info=read_bedpe(opts["-b"])
    f_val=parse_float(opts.get("-f"),1e-9) if opts.get("-f") else 1e-9
    slop_val=parse_int(opts.get("-slop"),0) if opts.get("-slop") else 0
    out=[]
    def end_interval(pe,end_idx,apply_slop=False):
        if end_idx==1:
            chrom,start,end,strand=pe.chrom1,pe.start1,pe.end1,pe.strand1
        else:
            chrom,start,end,strand=pe.chrom2,pe.start2,pe.end2,pe.strand2
        if apply_slop and slop_val:
            if opts.get("-ss"):
                if strand=="+":
                    end+=slop_val
                elif strand=="-":
                    start-=slop_val
                else:
                    start-=slop_val; end+=slop_val
            else:
                start-=slop_val; end+=slop_val
        return chrom,start,end,strand
    def ends_overlap(Ape,Aend,Bpe,Bend):
        ac,as_,ae,astr=end_interval(Ape,Aend,True)
        bc,bs,be,bstr=end_interval(Bpe,Bend,False)
        if ac!=bc: return False
        ov=min(ae,be)-max(as_,bs)
        if ov<=0: return False
        # original A end length (without slop) for fraction
        oc,os_,oe,ostr=end_interval(Ape,Aend,False)
        length=oe-os_
        # overlap fraction based on slopped interval or original? bedtools adds slop to A footprint before overlap, so fraction denominator may be slopped length. Use slopped length if slop.
        denom=(ae-as_) if slop_val else length
        if denom>0 and ov/denom < f_val-1e-12:
            return False
        if not opts.get("-is"):
            # strands enforced: must match? If either strand '.'? In observed B mismatch case, '+' vs '+' matched, '+' vs '-' mismatch. For '.' maybe no match like -s logic (only +/- equal)
            if not strand_match(astr,bstr,'s'):
                return False
        return True
    for A in a_recs:
        any_either=False; any_both=False
        qualifying=[]
        for B in b_recs:
            if opts.get("-rdn") and A.name==B.name:
                continue
            # either mapping orientation
            # A1 overlaps B1 or B2; A2 overlaps the other or any? Both requires each A end overlaps at least one B end, and the B ends used are distinct? Cross case ensures.
            a1_hits=[j for j in (1,2) if ends_overlap(A,1,B,j)]
            a2_hits=[j for j in (1,2) if ends_overlap(A,2,B,j)]
            either=bool(a1_hits or a2_hits)
            # both if there exists assignment of distinct B ends to A ends? Or could same B end overlap both A ends (large B end spanning) count as both? Original logic counts overlapping hits per end, might allow same B interval for both footprints. We'll allow any (not distinct) for now, except crossed distinction doesn't matter.
            both=bool(a1_hits and a2_hits)
            if either: any_either=True
            if both: any_both=True
            if type_val=="both" and both:
                qualifying.append(B)
            elif type_val=="either" and either:
                qualifying.append(B)
        if type_val in ("both","either"):
            for B in qualifying:
                out.append(f"{A.to_line()}\t{B.to_line()}\n")
        elif type_val=="neither":
            if not any_either:
                out.append(A.to_line()+"\n")
        elif type_val=="notboth":
            if not any_both:
                out.append(A.to_line()+"\n")
    sys.stdout.write("".join(out))
    return 0
