    out_report=[]
    for ci,chunk in enumerate(chunks):
        filename=f"{prefix}.{ci+1:05d}.bed"
        total=sum(r.end-r.start for r in chunk)
        with open(filename,"w") as fh:
            for r in chunk:
                fh.write(r.to_line()+"\n")
        out_report.append(f"{filename}\t{total}\t{len(chunk)}\n")
