import struct, sys
def reg2bin(beg,end):
    end-=1
    if beg>>14==end>>14: return 4681+(beg>>14)
    if beg>>17==end>>17: return 585+(beg>>17)
    if beg>>20==end>>20: return 73+(beg>>20)
    if beg>>23==end>>23: return 9+(beg>>23)
    if beg>>26==end>>26: return 1+(beg>>26)
    return 0
def make_bai(bam_path, refs):
    # refs list; chunk = entire records block: need find BGZF block boundaries
    data=open(bam_path,'rb').read()
    blocks=[]; off=0
    while off<len(data):
        bsize=struct.unpack_from('<H',data,off+16)[0]+1
        isize=struct.unpack_from('<I',data,off+bsize-4)[0]
        blocks.append((off,isize,bsize)); off+=bsize
    # header is first block (isize)
    # chunk begin at second block compressed offset, voffset within uncompressed block 0
    if len(blocks)>=2:
        chunk_beg=blocks[1][0]<<16
        # chunk end = start of EOF block voffset with offset = last records block uncompressed size
        last_data_block=blocks[-2] if blocks[-1][1]==0 else blocks[-1]
        chunk_end=(last_data_block[0]<<16)|last_data_block[1]
    else:
        chunk_beg=0; chunk_end=0
    out=b'BAI\x01'+struct.pack('<i',len(refs))
    bins=[0,1,9,73,585,4681]
    for name,length in refs:
        out+=struct.pack('<i',len(bins))
        for b in bins:
            out+=struct.pack('<Ii',b,1)+struct.pack('<QQ',chunk_beg,chunk_end)
        n_intv=(length//16384)+1
        out+=struct.pack('<i',n_intv)
        for i in range(n_intv): out+=struct.pack('<Q',chunk_beg)
    out+=struct.pack('<Q',0)
    open(bam_path+'.bai','wb').write(out)
make_bai('/tmp/t/test.bam',[('chr1',1000),('chr2',1000)])
PY
