        if max_depth is not None and d>max_depth: d=max_depth
        if scale!=1.0:
            return "%g" % (d*scale)
        return str(d)
    out=[]
    if opts.get("-trackline") or opts.get("-trackopts"):
        track_opts=opts.get("-trackopts") or ""
        if track_opts:
            out.append(f"track type=bedGraph {track_opts}\n")
        else:
            out.append("track type=bedGraph\n")
    mode="hist"
    if opts.get("-bg"): mode="bg"
    elif opts.get("-bga"): mode="bga"
    elif opts.get("-d"): mode="d"
    elif opts.get("-dz"): mode="dz"
    if mode in ("bg","bga"):
        block_chroms_seen=[]
        for chrom,ivs in blocks:
            if chrom not in block_chroms_seen: block_chroms_seen.append(chrom)
            for s,e,d in segments_for_block(chrom,ivs):
                dd=max_depth if (max_depth is not None and d>max_depth) else d
                if mode=="bg" and dd==0: continue
                out.append(f"{chrom}\t{s}\t{e}\t{fmt_depth(d)}\n")
        if mode=="bga":
            # Genome chromosomes never seen get a full zero segment (in genome order, after seen blocks)
            for chrom in genome.keys():
                if chrom not in block_chroms_seen:
                    out.append(f"{chrom}\t0\t{genome[chrom]}\t{fmt_depth(0)}\n")
    elif mode=="d":
        # For chromosomes with no records, reference prints all zero positions for the whole genome in genome order.
        # With blocks, order is: blocks in input order; missing chromosomes are itnterleaved by genome order in the reference's
        # chromosome iteration when input is grouped. For grouped input, genome order == block order typically.
        # Implement by iterating genome order but using block segments per chrom (aggregating blocks per chrom for -d is same as per-block if grouped)
        # To preserve per-block behaviour for ungrouped input, if there are repeated chrom blocks, use block order; else genome order.
        has_repeated=len(blocks)!=len(set(c for c,_ in blocks))
        if has_repeated:
            for chrom,ivs in blocks:
                for s,e,d in segments_for_block(chrom,ivs):
                    for pos in range(s,e):
                        out.append(f"{chrom}\t{pos+1}\t{fmt_depth(d)}\n")
        else:
            by={c:ivs for c,ivs in blocks}
            for chrom in genome.keys():
                for s,e,d in segments_for_block(chrom,by.get(chrom,[])):
                    for pos in range(s,e):
                        out.append(f"{chrom}\t{pos+1}\t{fmt_depth(d)}\n")
    elif mode=="dz":
        for chrom,ivs in blocks:
            for s,e,d in segments_for_block(chrom,ivs):
                if d==0: continue
                for pos in range(s,e):
                    out.append(f"{chrom}\t{pos}\t{fmt_depth(d)}\n")
    else:
        # Histogram with per-block accumulation (matches reference on ungrouped input)
        accum={}  # chrom -> {depth: bases}
        chrom_order_out=[]
        for chrom,ivs in blocks:
            segs=segments_for_block(chrom,ivs)
            hist_block={}
            for s,e,d in segs:
                dd=max_depth if (max_depth is not None and d>max_depth) else d
                hist_block[dd]=hist_block.get(dd,0)+(e-s)
            acc=accum.setdefault(chrom,{})
            for d,bases in hist_block.items():
                acc[d]=acc.get(d,0)+bases
            size=genome.get(chrom,0)
            for d in sorted(acc.keys()):
                bases=acc[d]; frac=bases/size if size else 0
                out.append(f"{chrom}\t{d}\t{bases}\t{size}\t{fmt_g(frac,6)}\n")
            if chrom not in chrom_order_out: chrom_order_out.append(chrom)
        # Missing genome chromosomes
        for chrom in genome.keys():
            if chrom not in accum:
                size=genome[chrom]
                accum[chrom]={0:size}
                out.append(f"{chrom}\t0\t{size}\t{size}\t{fmt_g(1.0 if size else 0,6)}\n")
        genome_total=sum(genome.values())
        genome_hist={}
        for chrom,acc in accum.items():
            for d,bases in acc.items():
                genome_hist[d]=genome_hist.get(d,0)+bases
        for d in sorted(genome_hist.keys()):
            bases=genome_hist[d]; frac=bases/genome_total if genome_total else 0
            out.append(f"genome\t{d}\t{bases}\t{genome_total}\t{fmt_g(frac,6)}\n")
    sys.stdout.write("".join(out))
    return 0

