            name=line.split("\t")[0]
            if name not in chrom_order: chrom_order.append(name)
        for r in records:
            if r.chrom not in chrom_order:
                raise BedError(f'Chromosome "{r.chrom}" undefined in {genome_path}\n')
    if opts.get("-header"):
        for h in info.header: sys.stdout.write(h+"\n")
    # Group records by chrom in map order (lexicographic) or genome order, preserving within-chrom file order
    from stdsort import libstdcxx_sort
    groups={}
    for r in records:
        groups.setdefault(r.chrom,[]).append(r)
    if chrom_order is None:
        chrom_order=sorted(groups.keys())
    def score_of(r):
        if r.fmt=="bed" and len(r.fields)>=5:
            try: return float(r.fields[4])
            except: return 0.0
        if r.fmt=="gff" and len(r.fields)>=6:
            try: return float(r.fields[5])
            except: return 0.0
        if r.fmt=="vcf" and len(r.fields)>=6:
            try: return float(r.fields[5])
            except: return 0.0
        return 0.0
    def size_of(r): return r.end-r.start
    def sort_list(rec_list, keyfunc):
        items=list(rec_list); keys=[keyfunc(r) for r in items]
        if len(items)>1:
            libstdcxx_sort(items,keys)
        return items
    records_sorted=[]
    if opts.get("-sizeA"):
        combined=[]
        for chrom in chrom_order:
            combined.extend(groups.get(chrom,[]))
        records_sorted=sort_list(combined, lambda r: size_of(r))
    elif opts.get("-sizeD"):
        combined=[]
        for chrom in chrom_order:
            combined.extend(groups.get(chrom,[]))
        records_sorted=sort_list(combined, lambda r: -size_of(r))
    elif opts.get("-chrThenSizeA"):
        for chrom in chrom_order:
            records_sorted.extend(sort_list(groups.get(chrom,[]), lambda r: size_of(r)))
    elif opts.get("-chrThenSizeD"):
        for chrom in chrom_order:
            records_sorted.extend(sort_list(groups.get(chrom,[]), lambda r: -size_of(r)))
    elif opts.get("-chrThenScoreA"):
        for chrom in chrom_order:
            records_sorted.extend(sort_list(groups.get(chrom,[]), lambda r: score_of(r)))
    elif opts.get("-chrThenScoreD"):
        for chrom in chrom_order:
            records_sorted.extend(sort_list(groups.get(chrom,[]), lambda r: -score_of(r)))
    else:
        for chrom in chrom_order:
            records_sorted.extend(sort_list(groups.get(chrom,[]), lambda r: r.start))
    sys.stdout.write("".join(r.to_line()+"\n" for r in records_sorted))
    return 0

'''
